        $scope.GetScribeDoctorList = function () {


            var reqObj = {
                "BranchId": $scope.HospitalId,
                "SubSpecializationIdArray": []
            }

            eHnoteMainAppointmentService.getAllUsersByDepartmentId(reqObj, onGetUsersSuccess, onGetUsersFailure);
            function onGetUsersSuccess(resp) {
                if (resp.rows.length > 0) {

                    $scope.allUserList = resp.rows;
                    $scope.allUserListForPopUps = [];
                    if ($scope.allUserList.length !== 0) {
                        // $scope.cacheStorageItem.allUserListForPopUps = $scope.allUserList || [];
                        $scope.allUserListForPopUps = $scope.allUserList || [];
                        $scope.clinicDoctorList = [];
                        $scope.Calendardoctorlist1 = [];


                        $scope.AllDoctorList = angular.copy($scope.allUserList);
                        $scope.AllDoctorAssitantList = angular.copy($scope.allUserList);

                        $scope.AllDoctorList = _.uniq($scope.AllDoctorList, false, function (p) { return p.DoctorID; });
                        $scope.AllDoctorList = $filter("filter")($scope.AllDoctorList, function (item) {
                            return item.RoleId === 1 || item.RoleId === 43;
                        });
                        $scope.AllDoctorAssitantList = _.uniq($scope.AllDoctorAssitantList, false, function (p) { return p.DoctorID; });
                        $scope.AllDoctorAssitantList1 = $filter("filter")($scope.AllDoctorAssitantList, function (item) {
                            return item.RoleId === 16 || item.RoleId === 73 || item.RoleId === 10;
                        });


                        $scope.AllDoctorAssitantList = $filter("filter")($scope.AllDoctorAssitantList, function (item) {
                            /*return item.RoleId === 16;*/
                            if ($scope.userLoginDetails.RoleID == 16) {
                                angular.forEach($scope.AllDoctorList, function (citem, $index) {
                                    $scope.selectedDoctorAssitant = "All";
                                    if (doctorinfo.doctordata.User[0].DoctorID !== citem.DoctorID) {
                                        $scope.selectedDoctorAssitant = userLoginDetails.displayName + '-' + userLoginDetails.RoleName;
                                    }

                                });
                            }
                            if ($scope.userLoginDetails.RoleID !== null) {
                                $scope.SelectedDoctor = "All";
                                $scope.SelectedDoctorname = $filter("filter")($scope.AllDoctorList, { "DoctorID": $scope.mainPatientProfileObj.DoctorId }, true)[0] || {};
                                /*      $scope.SelectedDoctor = $scope.SelectedDoctorname.FullName;*/
                                $scope.DoctorObj.DoctorID = $scope.SelectedDoctorname.DoctorID || 0;
                            }
                        });


                        //eHnoteMainAdminServices.GetAllWaitingRoomType().then(function (resp) {
                        //    $scope.RoomTypeList = resp.data;
                        //    $scope.RoomTypeList = $filter("filter")(resp.data, function (item, index) { return item.Id !== 6 && item.Id !== 5 && item.Id !== 3 && item.Id !== 8 });


                        //}, function (err) {
                        //    console.log(err);
                        //    alertify.error("Getting  Failed");
                        //});

                    }

                } else {
                    alertify.error("No Users Found in Selected Departments");
                    $scope.RoomDoctorsList = [];
                    $scope.FilteredRoomDoctorsList = [];
                }
            }

            function onGetUsersFailure(data) {
            }
        }
