        $scope.GetPatientPrescriptionDetails = function (type) {
            var params = {
                "PatientId": $scope.cacheStorageItem.patientid,
                "AppointmentId": appointmentinfo.AppointmentID,
                "ConsultationId": $scope.cacheStorageItem.PatientVisitId,
                "PageSize": 10,
                "PageNumber": 1,
                "BranchId": $scope.HospitalID
            }
            eHnotePatientDataService.GetPatientPrescriptionDetails(params).then(function (resp) {

                if (resp.data.rows.length > 0) {



                    $scope.cacheStorageItem.PrescriptionDetails = resp.data.rows || [];


                    //for (var i = $scope.cacheStorageItem.PrescriptionDetails.length - 1; i >= 0; i--) {
                    //    $scope.cacheStorageItem.PrescriptionDetails[i].PrescriptionDetails = $scope.cacheStorageItem.PrescriptionDetails[i].PrescriptionDetails || [];
                    //    if ($scope.cacheStorageItem.PrescriptionDetails[i].PrescriptionDetails.length === 0) {
                    //        //needto remove after db changes
                    //        $scope.cacheStorageItem.PrescriptionDetails.splice(i, 1);
                    //    }
                    //}


                    if ($scope.cacheStorageItem.PrescriptionDetails.length > 0) {
                        angular.forEach($scope.cacheStorageItem.PrescriptionDetails[0].PrescriptionDetails, function (bitem) {
                            bitem.CompleteAction = bitem.CompleteAction || null;
                            bitem.PatientInstructions = bitem.PatientInstructions || "";
                            bitem.DaysSupply = bitem.DaysSupply || "";
                            bitem.Quantity = bitem.Quantity || null;

                        });
                    }

                    $scope.AllergiesType = [];


                    if ($scope.cacheStorageItem.PrescriptionDetails.length > 0) {
                        angular.forEach($scope.cacheStorageItem.PrescriptionDetails, function (bitem) {
                            var filterArray = $filter("filter")(bitem.PrescriptionDetails, { "StopReason": "Adverse Reaction", "IsMedicationStopped": true }, true);



                            if (filterArray.length > 0) {
                                var obj = {
                                    "PatientDetailId": 0,
                                    "IsShowAllergySnomedAddInd": false,
                                    "AllergyId": filterArray[0].MedicationId || null,
                                    "RcopiaAllergyId": null,
                                    "AllergyName": filterArray[0].MedicationName || '',
                                    "OrganId": 4,
                                    "SeverityId": null,
                                    "SNOMEDId": null,
                                    "RxNormID": null,
                                    "NDCID": filterArray[0].DrugNDCID || null,
                                    "DrugGroupID": filterArray[0].DrugGroupID || null,
                                    "SeverityName": '',
                                    "ReactionId": 2, //filterArray[0].StopReasonId
                                    "StatusId": 1,
                                    "Duration": null,
                                    "AllergyTypeId": null,
                                    "IsEdit": true,
                                    "ShowNote": false,
                                    "ShowDateFormat": true,
                                    "ReactionName": "Adverse Reaction", //filterArray[0].StopReason
                                    "DurationDate": '',
                                    "StatusName": 'Active',
                                    "Remarks": '',
                                    "SnomedCode": '',
                                    "DurationType": 'D',
                                    "OnsetType": 'Date',
                                    "DiagnosisObject": 'D',
                                    "DeleteInd": 'N',

                                }
                                $scope.AllergiesType.push(obj);
                                $scope.cacheStorageItem.AllergyItems = $scope.cacheStorageItem.AllergyItems || [];
                                var i = 0;
                                if ($scope.cacheStorageItem.AllergyItems.length > 0) {
                                    angular.forEach($scope.cacheStorageItem.AllergyItems, function (item) {
                                        if (item.AllergyId === obj.AllergyId && item.DeleteInd == 'N') {
                                            // alertify.error('You have already entered this Allergy');
                                            i++;
                                        }
                                    });
                                }
                                if (i === 0) {
                                    $scope.cacheStorageItem.AllergyItems.push(obj);
                                }



                            }
                        });

                        // $scope.cacheStorageItem.AllergyItems = angular.copy($scope.AllergiesType);                                              
                    }

                    $scope.AddToCache();

                    if (type == true) {
                        $scope.openDirectEPrescribe();
                    }
                } else {
                    $scope.cacheStorageItem.PrescriptionDetails = [];
                }

            });
        }
        $scope.getPatientDetails = function () {
            var patientid = $scope.cacheStorageItem.PatientID || 0;

            eHnoteAuditServices.getPatientDetailsById(patientid, ongetPatientDetailsSuccess, ongetPatientDetailsError);
            function ongetPatientDetailsSuccess(data) {
                if (data !== undefined) {
                    if (data.Patient !== undefined) {
                        if (data.Patient.length > 0) {
                            $scope.PatinetProfileData = data.Patient;
                        }
                    }
                }
            }
            function ongetPatientDetailsError(error) {
                console.log(error);
            }
        }

