        $scope.checkConsultationStatus = function () {

            var object = {
                "AppointmentId": $scope.cacheStorageItem.appointmentid,
                "ConsultationId": $scope.cacheStorageItem.ConsultationID,
                "UserId": $scope.UserId,
                "ScreenType": "StartConsultation"
            };

            eHnotePatientDataService.CheckConsultationStatus(object).then(function (resp) {

                if (resp.data.ConsultationId !== undefined) {
                    $scope.cacheStorageItem.ConsultationID = resp.data.ConsultationId;
                    $scope.cacheStorageItem.PatientVisitId = resp.data.ConsultationId;
                }
                $scope.AddToCache();

            }, function (err) {
                if ($scope.ValidateConsultationData()) {
                    $scope.FinalSubmit(type, status, str);
                } else {
                    $scope.showPrintModulePopuP = false;
                    return false;
                }
            });
        };


