        $scope.$watch("cacheStorageItem.TonoMetryDetails", function (newVal, oldVal) {
            if ($scope.cacheStorageItem.TonoMetryDetails === undefined) { return; }
            if ($scope.cacheStorageItem.TonoMetryDetails.length > 0) {
                angular.forEach($scope.cacheStorageItem.TonoMetryDetails, function (item) {
                    item.IsInvDataAdded = false;
                    $scope.IopODCC = false
                    $scope.IopOsCC = false
                    if (item.ActiveInd === 'N') {
                        //item.IsInvDataAdded = true;
                    }
                    if (item.ActiveInd === 'Y') {
                        if (item.InvestigationId == 19 || item.InvestigationId == 20 || item.InvestigationId == 21 || item.InvestigationId == 22 || item.InvestigationId == 771 || item.InvestigationId == 814) {
                            if (item.Remarks != "" || item.BeforeDilationRightEye != "" || item.BeforeDilationLeftEye != "" || item.BeforeDilationTime != "" ||
                                item.AfterDilationRightEye != "" || item.AfterDilationLeftEye != "" || item.AfterDilationTime != "") {
                                item.IsInvDataAdded = true;
                            }
                            if (item.BeforeDilationODCC != "" || item.AfterDilationODCC != "") {
                                $scope.IopODCC = true;
                            }
                            if (item.BeforeDilationOSCC != "" || item.AfterDilationOSCC != "") {
                                $scope.IopOsCC = true;
                            }
                        }
                    }
                });
            }
            if ($scope.cacheStorageItem.TonoMetryDetails.length == 0) {
                $scope.cacheStorageItem.AvgTonometryODValue = "";
                $scope.cacheStorageItem.AvgTonometryOSValue = "";
                $scope.cacheStorageItem.MaxTonometryODValue = "";
                $scope.cacheStorageItem.MaxTonometryOSValue = "";
                $scope.cacheStorageItem.IOPInvName = "";
                $scope.cacheStorageItem.IOPInvId = "";
                //$scope.cacheStorageItem.TargetIOPPercentage = 0;
                //$scope.cacheStorageItem.TargetIOPODValue = 0;
                //$scope.cacheStorageItem.TargetIOPOSValue = 0;
            } else {
                let TonometryODValuesArray = [];
                let TonometryOSValuesArray = [];
                let TonometryODCCValuesArray = [];
                let TonometryOSCCValuesArray = [];
                let TotalODValue = 0;
                let TotalOSValue = 0;
                if ($scope.cacheStorageItem.TonoMetryDetails.length >= 3) {
                    angular.forEach($scope.cacheStorageItem.TonoMetryDetails, function (titem, ind) {
                        if (ind < 3) {
                            let OSValue = titem.BeforeDilationLeftEye || titem.AfterDilationLeftEye;
                            OSValue = parseFloat(OSValue);
                            TotalOSValue += OSValue;
                            let ODValue = titem.BeforeDilationRightEye || titem.AfterDilationRightEye;
                            ODValue = parseFloat(ODValue);
                            TotalODValue += ODValue;
                        }
                    });
                }

                angular.forEach($scope.cacheStorageItem.TonoMetryDetails, function (titem, ind) {
                    let OSValue = titem.BeforeDilationLeftEye || titem.AfterDilationLeftEye;
                    OSValue = parseFloat(OSValue);
                    TonometryOSValuesArray.push(OSValue);
                    let ODValue = titem.BeforeDilationRightEye || titem.AfterDilationRightEye;
                    ODValue = parseFloat(ODValue);
                    TonometryODValuesArray.push(ODValue);

                    let ODCCValue = titem.BeforeDilationODCC;
                    ODCCValue = parseFloat(ODCCValue) || "";
                    TonometryODCCValuesArray.push(ODCCValue);
                    let OSCCValue = titem.BeforeDilationOSCC;
                    OSCCValue = parseFloat(OSCCValue) || "";
                    TonometryOSCCValuesArray.push(OSCCValue);

                    $scope.cacheStorageItem.IOPInvName = titem.InvestigationDesc;
                    $scope.cacheStorageItem.IOPInvId = titem.InvestigationId;
                });

                $scope.cacheStorageItem.MaxTonometryODCCValue = 0;
                if (TonometryODCCValuesArray.length > 0) {
                    $scope.cacheStorageItem.MaxTonometryODCCValue = Math.max(...TonometryODCCValuesArray);
                } else {
                    $scope.cacheStorageItem.MaxTonometryODCCValue = 0;
                }
                $scope.cacheStorageItem.MaxTonometryOSCCValue = 0;
                if (TonometryOSCCValuesArray.length > 0) {
                    $scope.cacheStorageItem.MaxTonometryOSCCValue = Math.max(...TonometryOSCCValuesArray);
                } else {
                    $scope.cacheStorageItem.MaxTonometryOSCCValue = 0;
                }

                $scope.cacheStorageItem.AvgTonometryODValue = Number(TotalODValue / 3).toFixed(2);
                $scope.cacheStorageItem.AvgTonometryOSValue = Number(TotalOSValue / 3).toFixed(2);
                if (TonometryODValuesArray.length > 0) {
                    $scope.cacheStorageItem.MaxTonometryODValue = Math.max(...TonometryODValuesArray);
                } else {
                    $scope.cacheStorageItem.MaxTonometryODValue = 0;
                }
                if (TonometryOSValuesArray.length > 0) {
                    $scope.cacheStorageItem.MaxTonometryOSValue = Math.max(...TonometryOSValuesArray);
                } else {
                    $scope.cacheStorageItem.MaxTonometryOSValue = 0;
                }
                if (TonometryODCCValuesArray.length > 0) {
                    $scope.cacheStorageItem.MaxTonometryOSValue = Math.max(...TonometryOSValuesArray);
                } else {
                    $scope.cacheStorageItem.MaxTonometryOSValue = 0;
                }
            }
        }, true);

        $scope.bmiValueCal = function (val1, val2) {
            val1 = parseFloat(val1) || 0;
            val2 = parseFloat(val2) || 0;
            var height_in_meter = 0;
            var weight_in_kg = 0;
            var BMI;
            if (val1 !== 0) {
                height_in_meter = val1 / 100;
            }
            if (val2 !== 0) {
                weight_in_kg = val2;
            }
            BMI = weight_in_kg / (height_in_meter * height_in_meter);
            BMI = Math.round(BMI * 100) / 100;
            if (BMI < 18.5 && BMI > 0) {
                BMI = BMI + ' (Under Weight)';
            } else if (BMI >= 18.5 && BMI < 24.9) {
                BMI = BMI + ' (Normal Weight)';
            } else if (BMI >= 25 && BMI < 29.9) {
                BMI = BMI + ' (Over Weight)';
            } else if (BMI === 0) {
                BMI = "";
            } else {
                BMI = BMI + ' (Obesity)';
            }
            if ($scope.cacheStorageItem.Vitals.length === 16) {
                $scope.cacheStorageItem.Vitals.push({ "VitalID": 17, "VitalDesc": "BMI", "Value": "" });
            }
            if (val1 && val2) {
                $scope.cacheStorageItem.Vitals[16].Value = BMI;
            } else {
                $scope.cacheStorageItem.Vitals[16].Value = "";
            }
            $scope.AddToCache();
        };

