        $scope.CompareDilation = function (newDil,oldDil,newdilation,olddilation) {
            oldDil = oldDil || [];
            newDil = newDil||[];
            newdilation = newdilation||"";
            olddilation = olddilation || "";

            let oldText = "";
            let newText = "";
            let dltText = "";
            let deletedCount=0;


            // ---- Deleted ----
            oldDil.forEach(old => {
                let exists = newDil.find(n => n.DilationHistoryId == old.DilationHistoryId);

                if (!exists || exists.DeleteInd === "Y") {
                    let dDesc = $scope.formatDilationDesc(old, olddilation);
                    if (dDesc) {
                        dltText += dDesc + "\n\n";
                        deletedCount++;
                    }
                }
            });
            newDil.forEach(newItem => {
                if (newItem.DeleteInd === "Y") return;
                let oldItem = oldDil.find(x => x.DilationHistoryId == newItem.DilationHistoryId);

                let oldDesc = oldItem ? $scope.formatDilationDesc(oldItem, olddilation) : "";
                let newDesc = newItem ? $scope.formatDilationDesc(newItem, newdilation) : "";

                if (oldDesc !== newDesc) {
                    if (oldDesc) oldText += oldDesc + "\n\n";
                    if (newDesc) newText += newDesc + "\n\n";
                }
            });

            oldText = oldText.trim();
            newText = newText.trim();
            dltText = dltText.trim();

            if (oldText !== newText) {
                $scope.LogObj.LogArray.push({
                    LogId: 0,
                    ModuleId: 1,
                    ModuleName: "OUTPatient",
                    SubModuleId: 49,
                    SubModuleName: "Dilation",
                    ScreenType: "Dilation",
                    ActionType: oldText ? "Edited" : "Added",
                    OldActionDescription: oldText,
                    NewActionDescription: newText,
                    ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
                });
            }
            if (deletedCount>0) {
                $scope.LogObj.LogArray.push({
                    LogId: 0,
                    ModuleId: 1,
                    ModuleName: "OUTPatient",
                    SubModuleId: 49,
                    SubModuleName: "Dilation",
                    ScreenType: "Dilation",
                    ActionType: "Deleted",
                    OldActionDescription: dltText,
                    NewActionDescription: "",
                    ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
                });
            }

        }
        $scope.formatDilationDesc = function (item, IsDilation) {
            IsDilation = IsDilation||"";
            if (!item) return "";
            item.DilationDetails = item.DilationDetails||[];
            item.SelectedDilationMedArray = item.SelectedDilationMedArray||[];
            let time =
                item.DilationODStartTime ||
                item.DilationOSStartTime ||
                item.DilationOUStartTime ||
                item.DilationStartTime ||
                "";

            let formattedTime = "";
            if (time) {
                let dt = new Date(time);
                formattedTime = isNaN(dt.getTime())
                    ? time                   // Already like "4:21 AM"
                    : $filter("date")(dt, "hh:mm a");
            }


            // ------------------------------
            function hasData(x) {
                if (!x) return false;
                x.OrganId = x.OrganId||0;
               
                let medList="";
                if (item.DilationDetails.length > 0){
                 medList = (x.DilationDetails || [])
                    .filter(m => m.IsChecked && m.DeleteInd === "N");
                } else {
                    medList = (x.SelectedDilationMedArray || [])
                        .filter(m => m.IsChecked && m.DeleteInd === "N");
                }

                return (
                    medList.length > 0 ||
                    x.Frequency ||
                    formattedTime||
                    IsDilation||
                    x.IsDeferred||
                    x.IsRefused||
                    x.OrganId!=0||
                    x.Remarks
                );
            }

            if (!hasData(item)) return ""; 

            // Medication list
            let meds="";
            if (item.DilationDetails.length>0) {
                 meds = (item.DilationDetails || [])
                    .filter(m => m.IsChecked && m.DeleteInd === "N")
                    .map(m => m.DilationMedicationName)
                    .join(", ");
            }else{
                 meds = (item.SelectedDilationMedArray || [])
                    .filter(m => m.IsChecked && m.DeleteInd === "N")
                    .map(m => m.MedicationName)
                    .join(", ");
                }

            // Organ
            let organName = "";
            if (item.OrganId == 1) organName = "-OD";
            else if (item.OrganId == 2) organName = "-OS";
            else if (item.OrganId == 3) organName = "-OU";

            let dilation='';
            if (item.IsRefused) dilation = " -Refused";
            else if (item.IsDeferred) dilation = " -Deferred";

            let isdilation="";
            if (IsDilation) 
                isdilation = ` (${IsDilation})`;
            let dropsTxt = meds ? `Drops : ${meds}` : "";
            let freqTxt = item.Frequency ? `Frequency : ${item.Frequency}` : "";
            let stTxt = formattedTime ? `Start Time : ${formattedTime}` : "";
            let notesTxt = item.Remarks ? `Notes : ${item.Remarks}` : "";

            let parts = [];
            if (dropsTxt) parts.push(dropsTxt);
            if (freqTxt) parts.push(freqTxt);
            if (stTxt) parts.push(stTxt);
            if (notesTxt) parts.push(notesTxt);

            let desc = `Dilation ${isdilation}\n`;
            if (organName || dilation)desc += `Eye ${organName}${dilation}\n`;
            desc += parts.join(" | ");

            return desc.trim();
        };

