        $scope.$watch("cacheStorageItem.NineGazeExtraOcularDetails", function (newVal, oldVal) {

            if ($scope.cacheStorageItem.NineGazeExtraOcularDetails === undefined) { return; }
            angular.forEach($scope.cacheStorageItem.NineGazeExtraOcularDetails, function (item) {
                item.IsInvDataAdded = false;
                if (item.ActiveInd === 'N') {
                    item.IsInvDataAdded = true;
                }
                if (item.ActiveInd === 'Y') {
                    if (item.InvestigationId === 695) {
                        var hasData = false;

                        var checkData = function (data) {
                            if (!data) return false;
                            var found = false;
                            angular.forEach(data, function (pos) {
                                if (pos && ((pos.H && (pos.H.Amount || pos.H.Direction)) ||
                                    (pos.V && (pos.V.Amount || pos.V.Direction)))) {
                                    found = true;
                                }
                            });
                            return found;
                        };

                        hasData = checkData(item.ODDistance) ||
                            checkData(item.ODNear);

                        if (hasData) {
                            item.IsInvDataAdded = true;
                        }

                        item.AlphaPatternInd = false;
                        if (item.AlphabetPattern != "") {
                            item.IsInvDataAdded = true;
                            item.AlphaPatternInd = true;
                        }
                        /*item.ActiveInd = hasData ? 'Y' : 'N';*/

                    }
                    
                    if (item.InvestigationId === 18) {
                        item.ExtraOcularInd = false;
                        item.AlphaPatternInd = false;
                        if (item.RsrValue != "" || item.RIoValue != "" || item.RLrValue != "" || item.RPgValue != "" || item.RMrValue != "" || item.RIrValue != "" || item.RSoValue != "" || item.LIoValue != "" || item.LSrValue != "" || item.LMrValue != "" || item.LPgValue != "" || item.LLrValue != "" || item.LSoValue != "" || item.LIrValue != "" || item.LRemarks != "" || item.RRemarks != "") {
                            item.IsInvDataAdded = true;
                            item.ExtraOcularInd = true;
                        }
                        //if (item.AlphabetPattern != "") {
                        //    item.IsInvDataAdded = true;
                        //    item.AlphaPatternInd = true;
                        //}
                    }

                    if (item.InvestigationId === 2095) {
                        item.ExtraOcularInd = false;
                        if (item.RsrValue != "" || item.RIoValue != "" || item.RLrValue != "" || item.RPgValue != "" || item.RMrValue != "" || item.RIrValue != "" || item.RSoValue != "" || item.LIoValue != "" || item.LSrValue != "" || item.LMrValue != "" || item.LPgValue != "" || item.LLrValue != "" || item.LSoValue != "" || item.LIrValue != "" || item.LRemarks != "" || item.RRemarks != "") {
                            item.IsInvDataAdded = true;
                            item.ExtraOcularInd = true;
                        }
                    }
                    if (item.InvestigationId === 2096) {
                        if (item.DistanceRemarks != "" || item.NearRemarks != "") {
                            item.IsInvDataAdded = true;
                        }
                    }
                }
            });
        }, true);
