        $scope.getPatientOrderDetailsList = function () {
            $scope.PatientOrderInterpretationList = [];
            $scope.PatientImageStudyList = [];


            var params = {
                "PatientId": $scope.cacheStorageItem.patientid,
                "AppointmentId": $scope.cacheStorageItem.appointmentid || 0,
                "VisitId": $scope.cacheStorageItem.ConsultationID || 0,
            }

            eHnotePatientDataService.GetPatientOrderInterpretationDetailsByVisitId(params).then(function (resp) {
                if (resp.data.Status === "Success" && resp.data.rows.length > 0) {
                    $scope.PatientOrderInterpretationList = angular.copy(resp.data.rows);

                    // Collect all PatientImageStudyId requests
                    let imageStudyRequests = [];

                    angular.forEach($scope.PatientOrderInterpretationList, function (item) {
                        item.PatientImageStudyId = item.PatientImageStudyId || 0;
                        if (item.PatientImageStudyId !== 0) {
                            let iparams = { "PatientImageStudyId": item.PatientImageStudyId };
                            imageStudyRequests.push(
                                eHnotePatientDataService.GetPatientImageStudyDetailsById(iparams).then(function (imgResp) {
                                    if (imgResp.data.status === "Success" && imgResp.data.rows.length > 0) {
                                        angular.forEach(imgResp.data.rows, function (obj) {
                                            obj.PatientOrderId = item.PatientOrderId;
                                            $scope.PatientImageStudyList.push(obj);
                                        });
                                    }
                                })
                            );
                        }
                    });


                    Promise.all(imageStudyRequests).finally(function () {
                        $scope.GetPatientAppointmenthistroy(appointmentinfo.TreatmentPlanId, appointmentinfo.ConsultationId, appointmentinfo.AppointmentID);
                    });
                }
                else {

                    $scope.GetPatientAppointmenthistroy(appointmentinfo.TreatmentPlanId, appointmentinfo.ConsultationId, appointmentinfo.AppointmentID);
                }
            }).catch(function (err) {
                console.error(err);
                alertify.error("Fetching patient order details failed");
            });
        };


