        $scope.navToAddUpdatePatientProblemToRcopia = function (type) {

            console.log(type + "__type");


            var Problemobj = {
                "ConsultationID": $scope.cacheStorageItem.ConsultationID,
                "AppointmentID": $scope.cacheStorageItem.appointmentid,
                "HospitalId": $scope.HospitalId,
                "StatusFlag": 'D',
                "ConsultationDate": $filter('date')(new Date(), "yyyy-MM-dd"),
                "UserId": $scope.UserId,
                "AssessmentPlan": []
            }
            Problemobj.AssessmentPlan = $scope.cacheStorageItem.AssessmentPlan || [];
            eHnoteDiagnosisDataServices.AddupdateRcopiaConsultationAssessmentPlan(Problemobj).then(function (response) {



                if (response.data.Status === 'Success') {
                    $scope.selectedConsultationId = response.data.ConsultationID || 0;
                    if (response.data.AssessmentPlans.length > 0) {
                        angular.forEach($scope.cacheStorageItem.AssessmentPlan, function (Aitem) {
                            angular.forEach(response.data.AssessmentPlans, function (Bitem) {
                                if (Aitem.DiagnosisId == Bitem.DiagnosisId) {
                                    Aitem.ConsultationDiagnosisId = Bitem.ConsultationDiagnosisId;
                                }
                            });
                        });

                    }


                    var IsRcopiaLaunh = IsRcopiaLaunh || false;
                    $scope.ModifiedProblemsArray = [];
                    var params = {
                        "PatientId": $scope.cacheStorageItem.patientid,
                        "AppointmentId": appointmentinfo.AppointmentID,
                        "BranchId": $scope.HospitalID
                    }
                    eHnotePatientDataService.GetPatientUpdatedProblemsForRcopia(params).then(function (resp) {


                        $scope.ModifiedProblemsArray = resp.data.rows || [];

                        $scope.ModifiedProblemsArray = $filter("filter")($scope.ModifiedProblemsArray, { "IsRcopiaNotSend": false }) || [];

                        $scope.addUpdatePatientProblemsToRcopiaReqObj.DiagnosisList = [];
                        $scope.RcopiaPatientDiagnosisObj = getnewRcopiaPatientDiagnosisObj();
                        $scope.RcopiaAssessmentPlan = [];
                        if ($scope.ModifiedProblemsArray.length > 0) {





                            angular.forEach($scope.ModifiedProblemsArray, function (item) {

                                if (item.DeleteInd == 'N') {
                                    $scope.GeneralDiagnosisStatusName = "Active";
                                    $scope.Delete = "n";
                                    if (item.DiagnosisStatusId1 == 2) {
                                        $scope.GeneralDiagnosisStatusName = "Active";
                                        $scope.Delete = "n";
                                    }
                                    else if (item.DiagnosisStatusId1 == 1 || item.DiagnosisStatusId1 == 3 || item.DiagnosisStatusId1 == 6) {
                                        $scope.Delete = "y";
                                        $scope.GeneralDiagnosisStatusName = "InActive";
                                    }
                                    else if (item.DiagnosisStatusId1 == 4) {
                                        $scope.Delete = "y";
                                        $scope.GeneralDiagnosisStatusName = "Resolved";
                                    }
                                    else if (item.DiagnosisStatusId1 == 7 || item.DiagnosisStatusId1 == 5) {
                                        $scope.Delete = "y";
                                        $scope.GeneralDiagnosisStatusName = "Deleted";
                                    } else {
                                        $scope.GeneralDiagnosisStatusName = "Active";
                                        $scope.Delete = "n";
                                    }

                                    if (item.CodeSystem == "Snomed-CT") {
                                        var obj = {
                                            "Deleted": $scope.Delete,
                                            "DiagnosisStatusId": item.DiagnosisStatusId1 || 2,
                                            "Status": $scope.GeneralDiagnosisStatusName,
                                            "RcopiaProblemId": item.RcopiaProblemId || "",
                                            "OnsetDate": $filter('date')(new Date(), "MM/dd/yyyy HH:mm:ss"),
                                            "RcopiaID": item.RcopiaProblemId || "",
                                            "ExternalID": item.ConsultationDiagnosisId,
                                            "IsIcd11": false,
                                            "IsIcd10": false,
                                            "IsIcd9": false,
                                            "IsSnomedCode": true,
                                            "DiagnosisCode": '',        //ICD10CODE olny
                                            "DiagnosisName": '',
                                            "SnomedConceptID": item.ICD10CODE || '',
                                            "SnomedDescription": item.ICD10DIAGNAME,

                                        };
                                    }
                                    else {
                                        var obj = {
                                            "Deleted": $scope.Delete,
                                            "Status": $scope.GeneralDiagnosisStatusName,
                                            "DiagnosisStatusId": item.DiagnosisStatusId1 || 2,
                                            "RcopiaProblemId": item.RcopiaProblemId || "",
                                            "OnsetDate": $filter('date')(new Date(), "MM/dd/yyyy HH:mm:ss"),
                                            "RcopiaID": item.RcopiaProblemId || "",
                                            "ExternalID": item.ConsultationDiagnosisId,
                                            "IsIcd11": false,
                                            "IsIcd10": true,
                                            "IsIcd9": false,
                                            "IsSnomedCode": item.SnomedCode || '',
                                            "DiagnosisCode": item.ICD10CODE || '', //ICD10CODE olny
                                            "DiagnosisName": item.ICD10DIAGNAME,
                                            "SnomedConceptID": '',
                                            "SnomedDescription": '',

                                        };
                                    }
                                    $scope.addUpdatePatientProblemsToRcopiaReqObj.DiagnosisList.push(obj);
                                }
                            });
                        }



                        $scope.addUpdatePatientProblemsToRcopiaReqObj.ConsultationID = $scope.cacheStorageItem.ConsultationID || 0;
                        $scope.cacheStorageItem.ConsultationID = $scope.selectedConsultationId || 0;
                        $scope.addUpdatePatientProblemsToRcopiaReqObj.UserId = $scope.UserId;
                        $scope.addUpdatePatientProblemsToRcopiaReqObj.OrganizationId = $scope.HospitalID;



                        if ($scope.addUpdatePatientProblemsToRcopiaReqObj.DiagnosisList.length == 0) {

                            if (type === "direct") {
                                if ($scope.cacheStorageItem.CurrentSystemicMedicationsHistory.length > 0) {
                                    if ($scope.cacheStorageItem.CurrentSystemicMedicationsHistory.length > 0) {
                                        //$scope.navtoAddUpdateMedicationstoRcopia();
                                        $scope.GetPatientUpdatedPrescriptionsForRcopia(true);
                                    } else {
                                        $scope.openEPrescribe();
                                    }
                                }
                                else if ($scope.cacheStorageItem.PrescriptionDetails.length > 0) {
                                    if ($scope.cacheStorageItem.PrescriptionDetails[0].PrescriptionDetails.length > 0) {
                                        $scope.GetPatientUpdatedMedicalRXPrescriptionsForRcopia(true);

                                    }
                                    else {
                                        $scope.openEPrescribe();
                                    }
                                }
                                else {
                                    $scope.openEPrescribe();
                                }
                            } else {
                                $scope.medicalrxsUIB();
                            }


                        } else {

                            console.log($scope.addUpdatePatientProblemsToRcopiaReqObj);

                            eHnoteDiagnosisDataServices.addPatientProblemToRcopia($scope.addUpdatePatientProblemsToRcopiaReqObj).then(function (response) {



                                if (response.data.status === 'Success') {

                                    if (response.data.PatientProblemList.length > 0) {
                                        angular.forEach($scope.cacheStorageItem.AssessmentPlan, function (citem) {
                                            var list = $filter("filter")(response.data.PatientProblemList, { "ProblemId": citem.ConsultationDiagnosisId }, true) || [];
                                            if (list.length > 0) {
                                                citem.RcopiaProblemId = list[0].RcopiaProblemId;
                                            };
                                        });
                                    }

                                    if (type === "direct") {
                                        if ($scope.cacheStorageItem.CurrentSystemicMedicationsHistory.length > 0) {
                                            if ($scope.cacheStorageItem.CurrentSystemicMedicationsHistory.length > 0) {
                                                //$scope.navtoAddUpdateMedicationstoRcopia();
                                                $scope.GetPatientUpdatedPrescriptionsForRcopia(true);
                                            } else {
                                                $scope.openEPrescribe();
                                            }
                                        } else if ($scope.cacheStorageItem.PrescriptionDetails.length > 0) {
                                            if ($scope.cacheStorageItem.PrescriptionDetails[0].PrescriptionDetails.length > 0) {
                                                $scope.GetPatientUpdatedMedicalRXPrescriptionsForRcopia(true);

                                            }
                                            else {
                                                $scope.openEPrescribe();
                                            }
                                        } else {
                                            $scope.openEPrescribe();
                                        }
                                    } else {
                                        $scope.medicalrxsUIB();
                                    }
                                }



                            });
                        }





                    });



                }
            });



        };

