        $scope.DeleteProcInSuperBill = function (obj) {
            var r = alertify.confirm("<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre'>Are You Sure Want To Delete ?  </h4>", function () {
            $scope.LogObj.LogArray=[];
            let ProNames="";
            let deletedCount=0;
            let index = $scope.cacheStorageItem.SuperBillFinalObj.SuperBillSuggestedCodes.indexOf(obj);
            if (index > -1) {
                $scope.cacheStorageItem.SuperBillFinalObj.SuperBillSuggestedCodes[index].DeleteInd = "Y";
            }

            var SuperBillObj = {
                "UserId": $scope.UserId,
                "AppointmentId": $scope.cacheStorageItem.appointmentid,
                "VisitId": $scope.cacheStorageItem.PatientVisitId,
                "OrganizationId": $scope.HospitalID,
                "SuperBillRemarks": '',
                "SuperBillId": $scope.cacheStorageItem.SuperBillFinalObj.SuperBillId || '',
                "SuperBillArray": $scope.cacheStorageItem.SuperBillFinalObj.SuperBillSuggestedCodes || [],
                "Logs":{}
            };
            if (obj.DeleteInd === 'Y') {

                if (deletedCount > 0) ProNames += ', ';
                ProNames += `${obj.ProcedureCode} - ${obj.ProcedureName}`;
                deletedCount++;
            }
            if (deletedCount > 0) {
                $scope.LogObj.LogArray.push({
                    LogId: 0,
                    ModuleId: 1,
                    ModuleName: "OUTPatient",
                    SubModuleId: 58,
                    SubModuleName: "Super Bill",
                    ScreenType: "Super Bill(Summary)",
                    ActionType: "Deleted",
                    OldActionDescription: ProNames,
                    NewActionDescription: "",
                    ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
                });
            }
            if ($scope.LogObj.LogArray.length > 0) {
                SuperBillObj.Logs = $scope.LogObj || {};
            }
            eHnoteDiagnosisDataServices.AddupdateSuperBill(SuperBillObj).then(function (response) {

                if (response.data.Status === 'Success') {
                    if (response.data.SuperBillArray.length > 0) {
                        $scope.cacheStorageItem.SuperBillFinalObj.SuperBillSuggestedCodes = response.data.SuperBillArray || [];
                        if ($scope.cacheStorageItem.SuperBillFinalObj.SuperBillSuggestedCodes.length > 0) {
                            angular.forEach($scope.cacheStorageItem.SuperBillFinalObj.SuperBillSuggestedCodes, function (item) {
                                if (item.DeleteInd == "N") {
                                    if (item.DiagnosisArray.length > 0) {
                                        item.ShowDiagForAdd = true;
                                    } else {
                                        item.ShowDiagForAdd = false;
                                    }
                                }
                            });
                            $scope.LogObj.SuperBillSuggestedCodes = angular.copy($scope.cacheStorageItem.SuperBillFinalObj.SuperBillSuggestedCodes)||[];
                        }

                        /*$scope.cacheStorageItem.SuperBillFinalObj.SuperBillRemarks = $scope.SuperBillObject.Remarks || '';*/
                    }
                }
            });
            //if (obj.SuperBillItemId == 0) {
            //    let index = $scope.cacheStorageItem.SuperBillFinalObj.SuperBillSuggestedCodes.indexOf(obj);
            //    if (index > -1) {
            //        $scope.cacheStorageItem.SuperBillFinalObj.SuperBillSuggestedCodes.splice(index, 1);

            //    }

            //} else {
            //    let index = $scope.cacheStorageItem.SuperBillFinalObj.SuperBillSuggestedCodes.indexOf(obj);
            //    if (index > -1) {
            //        $scope.cacheStorageItem.SuperBillFinalObj.SuperBillSuggestedCodes[index].DeleteInd = true;

            //    }

            //}
            }, function () {
                r = "You pressed Cancel!";
            });
        };
