        $scope.ValidateConsultationData = function () {
            var keepGoing = true;
            //Prescription Checking
            $scope.cacheStorageItem.Prescriptions = $scope.cacheStorageItem.Prescriptions || [];
            if ($scope.cacheStorageItem.Prescriptions.length !== 0) {
                angular.forEach($scope.cacheStorageItem.Prescriptions, function (pre, index) {
                    if (keepGoing) {
                        pre.PrescriptionType = pre.PrescriptionType || "GenericMedicine";
                        if (pre.PrescriptionType === 'GenericMedicine') {
                            if (pre.PrescriptionData.ActiveInd === "Y") {

                                if (pre.PrescriptionData.Dosage === "") {
                                    alertify.error("Enter Dosage");
                                    keepGoing = false;
                                    $("#ulPresc").focus();
                                    return false;
                                }
                                if (pre.PrescriptionData.Frequency === "") {
                                    // if (pre.PrescriptionData.FrequencyObj.Code === '') {
                                    alertify.error("Enter Frequency");
                                    keepGoing = false;
                                    $("#ulPresc").focus();
                                    return false;
                                    // }
                                }
                                if (pre.PrescriptionData.DurationType !== "L" && pre.PrescriptionData.DurationType !== "C") {
                                    if (pre.PrescriptionData.Duration === "") {
                                        alertify.error("Enter Duration");
                                        keepGoing = false;
                                        $("#ulPresc").focus();
                                        return false;
                                    }
                                }
                            }
                        }

                        if (pre.PrescriptionType === 'TaperDrop') {
                            if (pre.PrescriptionData.ActiveInd === "Y") {
                                if (pre.PrescriptionData.TaperingArray.length > 0) {
                                    angular.forEach(pre.PrescriptionData.TaperingArray, function (mitem) {
                                        if (mitem.ActiveInd === "Y") {
                                            if (mitem.Dosage === "") {
                                                alertify.error("Enter Dosage");
                                                keepGoing = false;
                                                return false;
                                            }
                                            if (mitem.Duration === "") {
                                                alertify.error("Enter Duration");
                                                keepGoing = false;
                                                return false;
                                            }
                                        }
                                    });
                                }
                            }
                        }
                        if (pre.PrescriptionType === 'TaperTablet') {
                            if (pre.PrescriptionData.ActiveInd === "Y") {
                                if (pre.PrescriptionData.TaperingArray.length > 0) {
                                    angular.forEach(pre.PrescriptionData.TaperingArray, function (mitem) {
                                        if (mitem.ActiveInd === "Y") {
                                            if (mitem.Dosage === "") {
                                                alertify.error("Enter Dosage");
                                                keepGoing = false;
                                                return false;
                                            }
                                            if (mitem.Duration === "") {
                                                alertify.error("Enter Duration");
                                                keepGoing = false;
                                                return false;
                                            }
                                        }
                                    });
                                }
                            }
                        }
                    }
                });
            }
            if ($scope.cacheStorageItem.SurgeryArray.length !== 0) {
                angular.forEach($scope.cacheStorageItem.SurgeryArray, function (pre, index) {
                    if (keepGoing) {
                        pre.OrgSurgeryId = pre.OrgSurgeryId || 0;
                        if (pre.ActiveInd === "Y" && pre.OrgSurgeryId != 0) {
                            if (pre.OrganId === "") {
                                if ($scope.SpecializationId == '16') {
                                    alertify.error("Select Organ");
                                } else {
                                    alertify.error("Select Eye");
                                }

                                keepGoing = false;
                                $("#UlSurgery").focus();
                                return false;
                            }
                        }
                    }
                });
            }

            if ($scope.cacheStorageItem.PatientInvestigations.length !== 0) {
                angular.forEach($scope.cacheStorageItem.PatientInvestigations, function (pre, index) {
                    if (keepGoing) {
                        if (pre.StatusId === "4" && pre.RedoInvestigationInd === true) {
                            if (pre.RedoInvestigationRemarksId === "") {
                                alertify.error("Select Redo Remarks");
                                keepGoing = false;
                                $("#UlSurgery").focus();
                                return false;
                            }
                            if (pre.RedoInvestigationRemarksId === 1) {
                                if (pre.RedoInvestigationRemarks === "") {
                                    alertify.error("Enter Redo Remarks");
                                    keepGoing = false;
                                    $("#UlSurgery").focus();
                                    return false;
                                }
                            }
                        }
                    }
                });
            }
            return keepGoing;
        };

        $scope.getNewComplaints = function (val) {
            var object = {
                "ParentHospitalId": doctorinfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.ParentHospitalID,
                "SearchText": val,
                "PageSize": 10,
                "PageNumber": 1,
                "ChiefComplaintId": 0,
                "IsFrequent": 'N'

            };
            if (object.SearchText == '') {
                object.IsFrequent = 'Y';
            }
            return eHnoteSettingsDataService.GetMasterChiefComplaintConditionsUS(object).then(function (resp) {
                if (resp.data.count !== 0) {
                    if (resp.data.ChiefComplaint !== undefined) {
                        $scope.newChiefCompaintObj.AddComplaints = false;
                        return resp.data.ChiefComplaint.map(function (item) {
                            return item;
                        });
                    } else {
                        //$scope.obj.AddComplaints = true;
                        $scope.newChiefCompaintObj.AddComplaints = true;
                    }
                } else {
                    //$scope.obj.AddComplaints = true;
                    $scope.newChiefCompaintObj.AddComplaints = true;
                }
            });

        };


