            $scope.selectedPatientData.Patient = $scope.selectedPatientData.Patient || [];
            var appointmentinfo = eHnoteMasterDataService.getAppointmentInfo();
            appointmentinfo.PatientDetails = appointmentinfo.PatientDetails || {};
            if ($scope.selectedPatientData.Patient.length > 0) {
                appointmentinfo.PatientDetails = $scope.selectedPatientData.Patient[0] || {};
            }
            eHnoteMasterDataService.addAppointmentInfo(appointmentinfo);
