            text += `\n\nOS (Left Eye) : ${leftName}`;

            if (leftCells)
                text += `\nSelected Grids : ${leftCells}`;

            if (obj.LeftEyeRemarks)
                text += `\nRemarks : ${obj.LeftEyeRemarks}`;

