        function GetAutorefraObj() {
            return {
                "PatientFindingAutoRefractionId": 0,
                "InvestigationId": 0,
                "CategoryId": 1,
                "CategoryDesc": "Vision",
                "InvestigationDesc": "",
                "RightEyeValues": {
                    "Spherical": "",
                    "Cylindrical": "",
                    "Axis": ""
                },
                "LeftEyeValues": {
                    "Spherical": "",
                    "Cylindrical": "",
                    "Axis": ""
                },
                "Remarks": "",
                "ActiveInd": "Y"
            }
        };
        function formatAR(item, index) {
            if (!item) return '';
            const right = item.RightEyeValues || {};
            const left = item.LeftEyeValues || {};

            let desc = `AR${index + 1}: `;
            let odParts = [];
            if (right.Spherical) odParts.push(right.Spherical);
            if (right.Cylindrical) odParts.push(right.Cylindrical);
            let odText = odParts.join('/');
            if (right.Axis) odText += `*${right.Axis}`;

            desc += `OD- ${odText || ''}`;
            // desc += `OD- ${right.Spherical || ''}/${right.Cylindrical || ''}*${right.Axis || ''}`;
            let osParts = [];
            if (left.Spherical) osParts.push(left.Spherical);
            if (left.Cylindrical) osParts.push(left.Cylindrical);
            let osText = osParts.join('/');
            if (left.Axis) osText += `*${left.Axis}`;

            desc += ` , OS- ${osText || ''}`;
            // desc += ` , OS- ${left.Spherical || ''}/${left.Cylindrical || ''}*${left.Axis || ''}`;
            if (item.Remarks && item.Remarks.trim() !== '') {
                desc += ` , Remarks: ${item.Remarks.trim()}`;
            }
            if (item.GivenByName && item.GivenByName.trim() !== '') desc += ` , Added By: ${item.GivenByName}`;
            if (item.CreatedDateTime) desc += ` ${$filter('date')(item.CreatedDateTime, "MM-dd-yyyy hh:mm a")}`;

            return desc;
        }

        $scope.RemoveAutoRItem = function (item, invArray, index) {
            item.PatientFindingAutoRefractionId = item.PatientFindingAutoRefractionId || 0;
            if (item.PatientFindingAutoRefractionId != 0) {
                var r = alertify.confirm("<b class='txt-centre'>Confirm !</b><h4 class='txt-body-centre'>Are you sure  want to delete ?", function () {
                    var userId = $scope.UserId;
                    var appointmentInfo = $scope.appointmentInfo;
                    var AutoRefractionDetails = [];
                    let dltDescArr = [];
                    let deletedCount = 0;
                    if ($scope.cacheStorageItem.AutoRefractionDetails.length > 0) {
                        angular.forEach($scope.cacheStorageItem.AutoRefractionDetails, function (sitem) {
                            if (sitem.PatientFindingAutoRefractionId == item.PatientFindingAutoRefractionId) {
                                sitem.DeleteInd = "Y";
                            }
                        })
                        AutoRefractionDetails = angular.copy($scope.cacheStorageItem.AutoRefractionDetails);
                    }
                    var reqobj = {
                        "UserId": userId || 0,
                        "AppointmentID": appointmentInfo.AppointmentID || 0,
                        "AutoRefractionDetails": AutoRefractionDetails || [],
                        "Logs": {},
                    }
                    if (item.DeleteInd=='Y') {
                        dltDescArr.push(formatAR(item, index));
                        deletedCount++;
                    }
                    if (deletedCount > 0) {
                        const logObj = {
                            LogId: 0,
                            ModuleId: 1,
                            ModuleName: "OUTPatient",
                            SubModuleId: 50,
                            SubModuleName: "Vision and Perception",
                            ScreenType: "Auto Refraction",
                            ActionType: "Deleted",
                            OldActionDescription: dltDescArr.join('\n').trim(),
                            NewActionDescription: "",
                            ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
                        };
                        $scope.LogObj.LogArray.push(logObj);
                    }
                    if ($scope.LogObj.LogArray.length > 0) {
                        reqobj.Logs = $scope.LogObj || {};
                    }
                    eHnotePatientDataService.AddUpdateVisionPerceptionDetails(reqobj).then(function (resp) {
                        if (resp.data.Message == "Success") {
                            item.DeleteInd = "Y";
                            if ($scope.cacheStorageItem.AutoRefractionDetails.length > 0) {
                                angular.forEach($scope.cacheStorageItem.AutoRefractionDetails, function (sitem, index) {
                                    if (sitem.PatientFindingAutoRefractionId == item.PatientFindingAutoRefractionId) {
                                        sitem.DeleteInd = "Y";
                                        var removeindex = $scope.cacheStorageItem.AutoRefractionDetails.indexOf(sitem);
                                        if (removeindex > -1) {
                                            $scope.cacheStorageItem.AutoRefractionDetails.splice(removeindex, 1);
                                        }
                                    }
                                })
                            }
                            $scope.LogObj.AutoRefractionDetails = angular.copy($scope.cacheStorageItem.AutoRefractionDetails)||[];
                            alertify.success("Deleted Successfully");
                            let obj = GetAutorefraObj();
                            $scope.AddToCache();
                        }
                    }, function (errorr) {

                        console.log(error);
                    });
                }, function () {
                    r = "You pressed Cancel!";
                });
            } else {
                var index = invArray.indexOf(item);
                if (index > -1) {
                    invArray.splice(index, 1);
                    let obj = GetAutorefraObj();
                    //$scope.cacheStorageItem.AutoRefractionDetails.push(obj);
                }
            }

        }
