        function GetPGPObj() {
            return {
                "PatientFindingPGPRefractionId": 0,
                "InvestigationId": 0,
                "CategoryId": 1,
                "CategoryDesc": "Vision",
                "InvestigationDesc": "",
                "RightEyeValues": {
                    "Spherical": "",
                    "Cylindrical": "",
                    "Axis": "",
                    "Adition": "",
                    "PrismVt": "",
                    "BaseVt": "",
                    "PrismHz": "",
                    "BaseHz": ""
                },
                "LeftEyeValues": {
                    "Spherical": "",
                    "Cylindrical": "",
                    "Axis": "",
                    "Adition": "",
                    "PrismVt": "",
                    "BaseVt": "",
                    "PrismHz": "",
                    "BaseHz": ""
                },
                "Remarks": "",
                "SinceWhen": "",
                "SinceWhenId": 0,
                "Purpose": "",
                "PurposeId": 0,
                "ActiveInd": "Y"
            }
        };
        function formatPGP(item, index) {
            if (!item) return '';
            const right = item.RightEyeValues || {};
            const left = item.LeftEyeValues || {};

            let desc = `CGR${index + 1}: `;
            let odParts = [];
            if (right.Spherical) odParts.push(right.Spherical);
            if (right.Cylindrical) odParts.push(right.Cylindrical);
            let odText = odParts.join('/');
            if (right.Axis) odText += `*${right.Axis}`;

            desc += `OD- ${odText || ''}`;

            //desc += `OD- ${right.Spherical || ''}/${right.Cylindrical || ''}*${right.Axis || ''}`;
            if (right.Addition) desc += ` , Add: ${right.Addition}`;
            if (right.PrismVt) desc += ` , Prism(Vt): ${right.PrismVt}`;
            if (right.BaseVt) desc += ` , Base(Vt): ${right.BaseVt}`;
            if (right.PrismHz) desc += ` , Prism(Hz): ${right.PrismHz}`;
            if (right.BaseHz) desc += ` , Base(Hz): ${right.BaseHz}`;

            let osParts = [];
            if (left.Spherical) osParts.push(left.Spherical);
            if (left.Cylindrical) osParts.push(left.Cylindrical);
            let osText = osParts.join('/');
            if (left.Axis) osText += `*${left.Axis}`;

            desc += ` , OS- ${osText || ''}`;

            // desc += ` , OS- ${left.Spherical || ''}/${left.Cylindrical || ''}*${left.Axis || ''}`;
            if (left.Addition) desc += ` , Add: ${left.Addition}`;
            if (left.PrismVt) desc += ` , Prism(Vt): ${left.PrismVt}`;
            if (left.BaseVt) desc += ` , Base(Vt): ${left.BaseVt}`;
            if (left.PrismHz) desc += ` , Prism(Hz): ${left.PrismHz}`;
            if (left.BaseHz) desc += ` , Base(Hz): ${left.BaseHz}`;


            if (item.Remarks && item.Remarks.trim() !== '') desc += ` , Remarks: ${item.Remarks}`;
            if (item.Purpose && item.Purpose.trim() !== '') desc += ` , Purpose: ${item.Purpose}`;
            if (item.SinceWhen && item.SinceWhen.trim() !== '') desc += ` , Age: ${item.SinceWhen}`;
            if (item.GivenByName && item.GivenByName.trim() !== '') desc += ` , Added By: ${item.GivenByName}`;
            if (item.CreatedDateTime) desc += ` ${$filter('date')(item.CreatedDateTime, "MM-dd-yyyy hh:mm a")}`;


            return desc;
        }

        $scope.RemovePGPItem = function (item, invArray, index) {
            item.PatientFindingPGPRefractionId = item.PatientFindingPGPRefractionId || 0;
            if (item.PatientFindingPGPRefractionId != 0) {
                var r = alertify.confirm("<b class='txt-centre'>Confirm !</b><h4 class='txt-body-centre'>Are you sure want to delete   ?", function () {
                    var userId = $scope.UserId;
                    var appointmentInfo = $scope.appointmentInfo;
                    var PGPRefractionDetails = [];
                    let dltDescArr = [];
                    let deletedCount = 0;
                    if ($scope.cacheStorageItem.PGPRefractionDetails.length > 0) {
                        angular.forEach($scope.cacheStorageItem.PGPRefractionDetails, function (sitem) {
                            if (sitem.PatientFindingPGPRefractionId == item.PatientFindingPGPRefractionId) {
                                sitem.DeleteInd = "Y";
                            }
                        })
                        PGPRefractionDetails = angular.copy($scope.cacheStorageItem.PGPRefractionDetails);
                    }
                    var reqobj = {
                        "UserId": userId || 0,
                        "AppointmentID": appointmentInfo.AppointmentID || 0,
                        "PGPRefractionDetails": PGPRefractionDetails || [],
                        "Logs": {},
                    }
                    if (item.DeleteInd == 'Y') {
                        dltDescArr.push(formatPGP(item, index));
                        deletedCount++;
                    }
                    if (deletedCount > 0) {
                        const logObj = {
                            LogId: 0,
                            ModuleId: 1,
                            ModuleName: "OUTPatient",
                            SubModuleId: 50,
                            SubModuleName: "Vision and Perception",
                            ScreenType: "Current Glass Rx",
                            ActionType: "Deleted",
                            OldActionDescription: dltDescArr.join('\n').trim(),
                            NewActionDescription: "",
                            ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
                        };
                        $scope.LogObj.LogArray.push(logObj);
                    }
                    if ($scope.LogObj.LogArray.length > 0) {
                        reqobj.Logs = $scope.LogObj || {};
                    }
                    eHnotePatientDataService.AddUpdateVisionPerceptionDetails(reqobj).then(function (resp) {
                        if (resp.data.Message == "Success") {
                            item.DeleteInd = "Y";
                            if ($scope.cacheStorageItem.PGPRefractionDetails.length > 0) {
                                angular.forEach($scope.cacheStorageItem.PGPRefractionDetails, function (sitem, index) {
                                    if (sitem.PatientFindingPGPRefractionId == item.PatientFindingPGPRefractionId) {
                                        sitem.DeleteInd = "Y";
                                        var removeindex = $scope.cacheStorageItem.PGPRefractionDetails.indexOf(sitem);
                                        if (removeindex > -1) {
                                            $scope.cacheStorageItem.PGPRefractionDetails.splice(removeindex, 1);
                                        }
                                    }
                                })
                            }
                            item.DeleteInd = "Y";
                            $scope.LogObj.PGPRefractionDetails = angular.copy($scope.cacheStorageItem.PGPRefractionDetails)||[];
                            let obj = GetPGPObj();
                            /* $scope.cacheStorageItem.PGPRefractionDetails.push(obj);*/
                            alertify.success("Deleted Successfully");
                            /* $scope.cacheStorageItem.AutoRefractionDetails.push(obj);*/
                        }
                    }, function (errorr) {
                        console.log(error);
                    });
                }, function () {
                    r = "You pressed Cancel!";
                });
            } else {
                var index = invArray.indexOf(item);
                if (index > -1) {
                    invArray.splice(index, 1);
                }
                let obj = GetPGPObj();
                $scope.cacheStorageItem.PGPRefractionDetails.push(obj);
            }
        }
