        function formatFGRx(item, index) {
            if (!item) return '';

            let desc = `FGRx${index + 1}:`;

            // --- OD ---
            let odParts = [];
            if (item.RSpherical) odParts.push(item.RSpherical);
            if (item.RCylindrical) odParts.push(item.RCylindrical);
            let odText = odParts.join('/');
            if (item.RAxis) odText += `*${item.RAxis}`;

            if (odText) desc += `\nOD- ${odText}`;
            if (item.RAdition) desc += ` , Add: ${item.RAdition}`;
            if (item.RBCVA) desc += ` , VA(D): ${item.RBCVA}`;
            if (item.RBCNVA) desc += ` , VA(N): ${item.RBCNVA}`;
            if (item.RVAI) desc += ` , VA(I): ${item.RVAI}`;
            //if (item.RDuo) desc += ` , Duo: ${item.RDuo}`;
            //if (item.RCs) desc += ` , Cs: ${item.RCs}`;
            if (item.RPrismVt) desc += ` , Prism(Vt): ${item.RPrismVt}`;
            if (item.RBaseVt) desc += ` , Base(Vt): ${item.RBaseVt}`;
            if (item.RPrismHz) desc += ` , Prism(Hz): ${item.RPrismHz}`;
            if (item.RBaseHz) desc += ` , Base(Hz): ${item.RBaseHz}`;
            if (item.RType) desc += ` , Type: ${item.RType}`;

            // --- OS ---
            let osParts = [];
            if (item.LSpherical) osParts.push(item.LSpherical);
            if (item.LCylindrical) osParts.push(item.LCylindrical);
            let osText = osParts.join('/');
            if (item.LAxis) osText += `*${item.LAxis}`;

            if (osText) desc += `\nOS- ${osText}`;
            if (item.LAdition) desc += ` , Add: ${item.LAdition}`;
            if (item.LBCVA) desc += ` , VA(D): ${item.LBCVA}`;
            if (item.LBCNVA) desc += ` , VA(N): ${item.LBCNVA}`;
            if (item.LVAI) desc += ` , VA(I): ${item.LVAI}`;
            //if (item.LDuo) desc += ` , Duo: ${item.LDuo}`;
            //if (item.LCs) desc += ` , Cs: ${item.LCs}`;
            if (item.LPrismVt) desc += ` , Prism(Vt): ${item.LPrismVt}`;
            if (item.LBaseVt) desc += ` , Base(Vt): ${item.LBaseVt}`;
            if (item.LPrismHz) desc += ` , Prism(Hz): ${item.LPrismHz}`;
            if (item.LBaseHz) desc += ` , Base(Hz): ${item.LBaseHz}`;
            if (item.LType) desc += ` , Type: ${item.LType}`;

            // --- Common fields ---
            let common = [];
            if (item.LensTypeName && item.LensTypeName.trim() !== '') common.push(`Type Of Lens: ${item.LensTypeName}`);
            if (item.ModeOfWearName && item.ModeOfWearName.trim() !== '') common.push(`Mode Of Wear: ${item.ModeOfWearName}`);
            if (item.FrameMaterialName && item.FrameMaterialName.trim() !== '') common.push(`Frame Material: ${item.FrameMaterialName}`);
            if (item.LensMaterialName && item.LensMaterialName.trim() !== '') common.push(`Type Of Lens Material: ${item.LensMaterialName}`);
            if (item.ExpirationDate && item.ExpirationDate.trim() !== '') common.push(`Expiration Date: ${item.ExpirationDate, "MM-dd-yyyy"}`);
            if (item.Remarks && item.Remarks.trim() !== '') common.push(`Remarks: ${item.Remarks}`);
            if (item.Purpose && item.Purpose.trim() !== '') common.push(`Purpose: ${item.Purpose}`);
            if (item.ExpirationYearName && item.ExpirationYearName.trim() !== '') common.push(`Expiration Year: ${item.ExpirationYearName}`);
            if (item.EnteredbyName && item.EnteredbyName.trim() !== '') common.push(`Entered by: ${item.EnteredbyName}`);
            if (item.PrescribedbyName && item.PrescribedbyName.trim() !== '') common.push(`Prescribed by: ${item.PrescribedbyName}`);
            if (item.PDDistanceOU && item.PDDistanceOU.trim() !== '') common.push(`PD Distance OU: ${item.PDDistanceOU} Mm`);
            if (item.PDNearOU && item.PDNearOU.trim() !== '') common.push(`PD Near OU: ${item.PDNearOU} Mm`);
            if (item.GivenByName && item.GivenByName.trim() !== '') common.push(`Added By: ${item.GivenByName}`);
            if (item.CreatedDateTime) common.push(` ${$filter('date')(item.CreatedDateTime, "MM-dd-yyyy hh:mm a")}`);
            if (item.LensCoating && item.LensCoating.length > 0) {
                const coatingNames = item.LensCoating
                    .filter(c => c.DeleteInd !== 'Y')
                    .map(c => c.Name)
                    .join(', ');
                if (coatingNames) common.push(`Lens Coating: ${coatingNames}`);
            }

            if (common.length > 0) desc += `\n${common.join(' , ')}`;

            return desc;
        }

