        function formatTono(item) {
            if (!item) return '';

            let text = [];

            if (item.DropMedicineName) text.push(`Drops: ${item.DropMedicineName}`);
            if (item.InvestigationDesc) text.push(`Device: ${item.InvestigationDesc}`);

            if (item.BeforeDilationRightEye || item.BeforeDilationLeftEye)
                text.push(`OD MmHg: ${item.BeforeDilationRightEye || ''}, OS MmHg: ${item.BeforeDilationLeftEye || ''}`);

            if (item.BeforeDilationTime) text.push(`Time: ${item.BeforeDilationTime}`);

            if (item.BeforeDilationODCC || item.BeforeDilationOSCC)
                text.push(`OD CC MmHg: ${item.BeforeDilationODCC || ''}, OS CC MmHg: ${item.BeforeDilationOSCC || ''}`);

            if (item.DropGivenByName) text.push(`Given By: ${item.DropGivenByName}`);
            if (item.Remarks) text.push(`Remarks: ${item.Remarks}`);

            return text.join(' , ').trim();
        }

