        function formatPachy(item, idx) {
            if (!item) return "";

            const OD = item.RightEye || item.RightEyeValue || "";
            const OS = item.LeftEye || item.LeftEyeValue || "";
            const given = item.PachyGivenByName || "";
            const date = item.CreatedDt ? $filter('date')(item.CreatedDt, "MM-dd-yyyy") : "";
            const time = item.PachymetryTime || "";
            const remarks = item.Remarks?.trim() || "";

            let parts = [];

            if (OD) parts.push(`OD-${OD}`);
            if (OS) parts.push(`OS-${OS}`);
            if (date) parts.push(`Date-${date}`.trim());
            if (time) parts.push(`Time- ${time}`.trim());
            if (given) parts.push(`Given By-${given}`);
            if (remarks) parts.push(`Remarks-${remarks}`);

            return `Pachy${idx + 1}: ${parts.join(" , ")}`;
        }

