        function buildSingleRemarkLog(investigationId, item, remark) {
            item = item || '';
            remark = remark || '';
            const MAP = {
                23: "Lids",
                24: "Conjunctiva",
                25: "Sclera",
                26: "Cornea",
                27: "Anterior Chamber",
                28: "Iris",
                29: "Pupil",
                30: "Lens",
                744: "Lashes",
                746: "Adnexa"
            };


            // Normal items
            let title = MAP[investigationId] || "Anterior Segment";
            let eyes = remark.OrganId == 1 ? "OD (Right Eye)" : "OS (Left Eye)";
            let notes = remark.Notes ? ` (Notes: ${remark.Notes})` : "";

            return `
              ${title} :
              ${eyes} - ${remark.FindingValue}${notes}
               `;
        }
        function buildPosteriorSingleRemarkLog(investigationId, item, remark) {

            const MAP = {
                34: "Vitreous",
                35: "Retina",
                33: "Macula",
                2144: "Disc/ON",
                2146: "Choroid",
                39: "Blood Vessels",
                40: "Periphery"
            };


            // Normal items
            let title = MAP[investigationId] || "Posterior Segment";
            let eyes = remark.OrganId == 1 ? "OD (Right Eye)" : "OS (Left Eye)";
            let notes = remark.Notes ? ` (Notes: ${remark.Notes})` : "";

            return `
                ${title} :
               ${eyes} - ${remark.FindingValue}${notes}
                 `;
        }

