                        if (item.DrugType) parts +=(' Drug Type :' + item.DrugType);
                        if (date) parts += (' Drug DurationDate :' + date);
                        if (duration) parts += (' Drug Duration :' + duration);
                        if (item.DrugArray && item.DrugArray.length > 0) parts +=(' Drugs :' + (item.DrugArray || []).map(d => d.HabitsDescription).join(', '));
                        if (item.DrugQuantityName) parts +=(' Drug QuantityName :' + item.DrugQuantityName);
