        $scope.DeleteCheifComplaints = function (obs, index) {
            $scope.LogObj.LogArray=[];
            var r = alertify.confirm("<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre'>Are You Sure Want To Delete  ?  </h4>", function () {
                let cheifcomplintNames='';
                let deletedCount=0;
                var index = $scope.cacheStorageItem.ChiefComplaints.indexOf(obs);
                if (index > -1) {
                    //if (obs.PatientChiefComplaintId !== 0) {
                    //    $scope.cacheStorageItem.ChiefComplaints[index].ActiveInd = "N";
                    //} else {
                    //    $scope.cacheStorageItem.ChiefComplaints.splice(index, 1);
                    //}
                    if (obs.PatientChiefComplaintId !== 0) {
                        $scope.cacheStorageItem.ChiefComplaints[index].ActiveInd = "N";

                        $scope.ChangedHPIDiscription($scope.cacheStorageItem.ChiefComplaints);
                        var CheifComplaitsobject = {
                            "VisitId": $scope.cacheStorageItem.PatientVisitId || 0,
                            "AppointmentID": $scope.cacheStorageItem.appointmentid,
                            "OrganizationId": $scope.HospitalId,
                            "UserId": $scope.UserId,
                            "ConsultationDate": $scope.cacheStorageItem.ConsultationDate || "",
                            "ChiefComplaintNotes": $scope.cacheStorageItem.ChiefComplaints || [],
                            "HistoryOfPresentIllness": $scope.cacheStorageItem.HistoryOfPresentIllness || '',
                            "Logs":{},
                        }
                        if (obs.ActiveInd === 'N') {
                            if (deletedCount > 0) cheifcomplintNames += '\n ';
                            cheifcomplintNames += `${obs.Description || ""}`;
                            deletedCount++;
                        }
                        let newDesc="";
                        let NewActionDescription="";
                        let OldActionDescription="";
                        if (deletedCount > 0) {
                            if (cheifcomplintNames) {
                                newDesc += (newDesc ? "\n\n" : "") + "Cheif Complints :\n" + cheifcomplintNames;
                            }
                            $scope.LogObj.LogArray.push({
                                LogId: 0,
                                ModuleId: 1,
                                ModuleName: "OUTPatient",
                                SubModuleId: 47,
                                SubModuleName: "Chief Complaints",
                                ScreenType: "Chief Complaints(Summary)",
                                ActionType: "Deleted",
                                OldActionDescription: newDesc,
                                NewActionDescription: "",
                                ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
                            });
                        }
                        if ($scope.cacheStorageItem.HistoryOfPresentIllness != "" || $scope.LogObj.HistoryOfPresentIllness != '') {
                            if ($scope.cacheStorageItem.HistoryOfPresentIllness != $scope.LogObj.HistoryOfPresentIllness) {
                                if ($scope.cacheStorageItem.HistoryOfPresentIllness)
                                    NewActionDescription += `${NewActionDescription ? '\n ' : ''}HPI : ${$scope.cacheStorageItem.HistoryOfPresentIllness}`;
                                if ($scope.LogObj.HistoryOfPresentIllness)
                                    OldActionDescription += `${OldActionDescription ? '\n' : ''}HPI : ${$scope.LogObj.HistoryOfPresentIllness}`;
                            }
                        }
                        if (NewActionDescription !== "" || OldActionDescription !== "") {
                            let obj = {
                                "LogId": 0,
                                "ModuleId": 1,
                                "ModuleName": "OUTPatient",
                                "SubModuleId": 47,
                                "SubModuleName": "Chief Complaints",
                                "ScreenType": "Chief Complaints",
                                "ActionType": "Edited",
                                "OldActionDescription": OldActionDescription,
                                "NewActionDescription": NewActionDescription,
                                "ActionDateTime": $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss"),
                            };
                            $scope.LogObj.LogArray.push(obj);
                        }
                        if ($scope.LogObj.LogArray.length > 0) {
                            CheifComplaitsobject.Logs = $scope.LogObj || {};
                        }
                        eHnoteDiagnosisDataServices.AddUpdateChiefComplaints(CheifComplaitsobject).then(function (resp) {
                            if (resp.data.Status === 'Success') {

                                $scope.cacheStorageItem.ChiefComplaints.splice(index, 1);
                                if ($scope.cacheStorageItem.ChiefComplaints.length==0) {
                                    $scope.cacheStorageItem.HistoryOfPresentIllness='';
                                }
                                $scope.LogObj.HistoryOfPresentIllness = $scope.cacheStorageItem.HistoryOfPresentIllness||"";
                            }
                            $scope.AddToCache();
                        });
                    }
                }
                $scope.AddToCache();
            }, function () {
                r = "You pressed Cancel!";
            });
        };


