        $scope.RemoveGlassRX = function (item) {
            var r = alertify.confirm("<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre'>Are You Sure To Delete The GlassRx Data ?  </h4>", function () {
                if ($scope.cacheStorageItem.GlassDetails.length > 0) {
                    angular.forEach($scope.cacheStorageItem.GlassDetails, function (gitem, index) {

                        if (gitem.InvestigationId === 43) {
                            if (gitem.PatientFindingGlassId == item.PatientFindingGlassId) {
                                gitem.IsInvDataAdded = false;
                                gitem.ActiveInd = 'N';
                                if ($scope.cacheStorageItem.GlassRxRefractionDetails.length > 0) {
                                    var indexind = $scope.cacheStorageItem.GlassRxRefractionDetails[index];
                                    if (indexind != undefined) {
                                        $scope.cacheStorageItem.GlassRxRefractionDetails[index].ActiveInd = 'N';
                                    }
                                }
                            }
                        }
                    });

                    var GlassRXDetailsobject = {
                        "ConsultationID": $scope.cacheStorageItem.ConsultationID || 0,
                        "AppointmentID": $scope.cacheStorageItem.appointmentid,
                        "OrganizationId": $scope.HospitalId,
                        "UserId": $scope.UserId,
                        /* "StatusFlag": 'D',*/
                        "ConsultationDate": $scope.cacheStorageItem.ConsultationDate || "",
                        "GlassRXDetails": $scope.cacheStorageItem.GlassDetails || [],
                        "FinalGlassRxDetails": $scope.cacheStorageItem.GlassRxRefractionDetails || [],

                    }

                    eHnotePatientDataService.AddUpdateVisionPerceptionDetails(GlassRXDetailsobject).then(function (response) {
                        if (response.data.Message === 'Success') {

                            var index = $scope.cacheStorageItem.GlassDetails.indexOf(item);
                            if (index > -1) {
                                if (item.InvestigationId === 43) {
                                    $scope.cacheStorageItem.GlassDetails.splice(index, 1);
                                }
                            }
                            var indexind = $scope.cacheStorageItem.GlassRxRefractionDetails[index];
                            if (indexind != undefined) {
                                $scope.cacheStorageItem.GlassRxRefractionDetails.splice(index, 1);
                            }

                            alertify.success("GlassRX Deleted successfully!");
                        }


                    });
                    $scope.AddToCache();
                }
            }, function () {
                r = "You pressed Cancel!";
            });
        }
        $scope.deleteLeftPosteriorCDR = function (inv) {
            $scope.LogObj.LogArray=[];
            let osHas =
                inv.LHorizontal || inv.LVertical || inv.LDPS;

            let deleteLog = "";

            if (osHas) {
                let parts = [];

                if (inv.LHorizontal) parts.push(`HZ: ${inv.LHorizontal}`);
                if (inv.LVertical) parts.push(`VT: ${inv.LVertical}`);
                if (inv.LDPS) parts.push(`DPS: ${inv.LDPS}`);


                deleteLog =
                    `CDR :
                  OS (Left Eye) - ${parts.join(", ")}`;
            }
            inv.LHorizontal = "";
            inv.LVertical = "";
            inv.LDPS = "";
            if (inv.LHorizontal === "" && inv.LVertical === "" && inv.LDPS === "" && inv.RHorizontal === "" && inv.RVertical === "" && inv.RDPS === "") {
                inv.ActiveInd = 'N';
            }

            if (deleteLog.trim() !== "") {
                $scope.LogObj.LogArray.push({
                    LogId: 0,
                    ModuleId: 1,
                    ModuleName: "OUTPatient",
                    SubModuleId: 52,
                    SubModuleName: "Examination",
                    ScreenType: "Posterior Segment from Summary",
                    ActionType: "Deleted",
                    OldActionDescription: `${deleteLog}`,
                    NewActionDescription: "",
                    ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
                });
            }
            var obj = {
                "HospitalId": $scope.HospitalId,
                "UserId": $scope.UserId,
                "PatientId": $scope.cacheStorageItem.patientid,
                "AppointmentId": $scope.cacheStorageItem.appointmentid,
                "PoteriorSegmentArrayNew": $scope.cacheStorageItem.PoteriorSegmentArrayNew || [],
                "VisitId": $scope.cacheStorageItem.PatientVisitId || 0,
                "Logs":{}
            }
            if ($scope.LogObj.LogArray.length > 0) {
                obj.Logs = $scope.LogObj || {};
            }
            eHnoteDiagnosisDataServices.AddupdateExaminationsData(obj).then(function (response) {
                if (response.data.data.Status === 'Success') {
                    angular.forEach($scope.cacheStorageItem.PoteriorSegmentArrayNew, function (item, index) {
                        if (item.ActiveInd == 'N') {
                            $scope.cacheStorageItem.PoteriorSegmentArrayNew.splice(index, 1);
                        }
                        $scope.AddToCache();
                    });
                    $scope.CDRarray = [];
                    if ($scope.cacheStorageItem.PoteriorSegmentArrayNew.length > 0) {
                        angular.forEach($scope.cacheStorageItem.PoteriorSegmentArrayNew, function (citem) {
                            if (citem.ActiveInd == 'Y' && citem.InvestigationId == 32) {
                                $scope.CDRarray.push(citem);
                            }
                        });
                    }
                    if ($scope.CDRarray.length > 0) {
                        $scope.Accordionobj.IsPoteriorSegmentOpen = true;
                    }
                    else {
                        $scope.Accordionobj.IsPoteriorSegmentOpen = false;
                    }
                }

            });
        }
