        $scope.DeleteHealthGoalData = function (item) {
            $scope.LogObj.LogArray = [];

            var r = alertify.confirm("<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre'>Are You Sure To Delete The Patient Health Goal Data ?  </h4>", function () {
                let dltcount = 0;
                let dltallergyNames = '';
                let date = '';
                let enddate = '';

                var GoalObj = {
                    "HospitalId": $scope.HospitalId,
                    "UserId": $scope.UserId,
                    "PatientId": $scope.cacheStorageItem.patientid,
                    "VisitId": $scope.cacheStorageItem.PatientVisitId,
                    "AppointmentID": $scope.cacheStorageItem.appointmentid,
                    "PatientHealthGoals": [],
                    "AllergyRemarks": $scope.cacheStorageItem.AllergyRemarks || "",
                    "SurgicalRemarks": $scope.cacheStorageItem.SurgicalRemarks || "",
                    "CurrentSystemicRemarks": $scope.cacheStorageItem.CurrentSystemicRemarks || "",
                    "CurrentEyeRemarks": $scope.cacheStorageItem.CurrentEyeRemarks || "",
                    "SystemicHistoryRemarks": $scope.cacheStorageItem.SystemicHistoryRemarks || "",
                    "OccularHistoryRemarks": $scope.cacheStorageItem.OccularHistoryRemarks || "",
                    "OcularSurgicalHistoryRemarks": $scope.cacheStorageItem.OcularSurgicalHistoryRemarks || "",
                    "FamilyHistoryRemarks": $scope.cacheStorageItem.FamilyHistoryRemarks || "",
                    "FunctionalStatusRemarks": $scope.cacheStorageItem.FunctionalStatusRemarks || "",
                    "VaccinationHistoryRemarks": $scope.cacheStorageItem.VaccinationHistoryRemarks || "",
                    "BirthHistoryRemarks": $scope.cacheStorageItem.BirthHistoryRemarks || "",
                    "NutritionalHistoryRemarks": $scope.cacheStorageItem.NutritionalHistoryRemarks || "",
                    "MenstrualHistoryRemarks": $scope.cacheStorageItem.MenstrualHistoryRemarks || "",
                    "PhysicalEvaluationRemarks": $scope.cacheStorageItem.PhysicalEvaluationRemarks || "",
                    "PsychiatryRemarks": $scope.cacheStorageItem.PsychiatryRemarks || "",
                    "HealthGoalsRemarks": $scope.cacheStorageItem.HealthGoalsRemarks || "",
                    "LabInvestigationsRemarks": $scope.cacheStorageItem.LabInvestigationsRemarks || "",
                    "ImplantRemarks": $scope.cacheStorageItem.ImplantRemarks || "",
                    "PsychologicalObservRemarks": $scope.cacheStorageItem.PsychologicalObservRemarks || "",
                    "VitalsRemarks": $scope.cacheStorageItem.VitalsRemarks || "",
                    "LifestyleHistoryRemarks": $scope.cacheStorageItem.LifestyleHistoryRemarks || "",
                    "Logs": {},

                }
                item.DeleteInd = 'Y';
                GoalObj.PatientHealthGoals.push(item);
                if (item.DeleteInd === 'Y') {
                    if (dltcount > 0) dltallergyNames += ', ';
                    item.StartDate = item.StartDate || ''
                    item.TargetDate = item.TargetDate || ''
                    if (item.StartDate != '') {
                        date = $filter('date')(item.StartDate, 'MM-dd-yyyy');
                    }
                    if (item.TargetDate != '') {
                        enddate = $filter('date')(item.TargetDate, 'MM-dd-yyyy');
                    }
                    if (item.HealthConcernDescription) dltallergyNames += ('Discreption :' + item.GoalDescription);
                    if (item.ExpressedBy) dltallergyNames += (' Expressed By :' + item.ExpressedBy);
                    if (date) dltallergyNames += (' Start Date :' + date);
                    if (enddate) dltallergyNames += (' End Date :' + enddate);
                    if (item.Status) dltallergyNames += (' Status :' + item.Status);
                    dltcount++;
                }
                if (dltcount > 0) {
                    let description = (dltcount > 0)
                        ? `Health Goals - ${dltallergyNames.toUpperCase()}`
                        : '';

                    let obj = {
                        "LogId": 0,
                        "ModuleId": 1,
                        "ModuleName": "OUTPatient",
                        "SubModuleId": 48,
                        "SubModuleName": "ROS",
                        "ScreenType": "ROS(Health Concerns & Goals)",
                        "ActionType": "Deleted",
                        "OldActionDescription": description,
                        "NewActionDescription": '',
                        "ActionDateTime": $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss"),
                    };
                    $scope.LogObj.LogArray.push(obj);
                }
                if ($scope.LogObj.LogArray.length > 0) {
                    GoalObj.Logs = $scope.LogObj || {};
                }

                eHnoteDiagnosisDataServices.AddupdateROSData(GoalObj).then(function (response) {
                    if (response.data.Status === 'Success') {
                        alertify.success("Health Goal Deleted successfully!");
                        /*$scope.cacheStorageItem.HealthGoalsArray = response.data.PatientHealthGoals || [];*/
                        //$scope.cacheStorageItem.HealthGoalsArray = response.data.PatientGoals || [];
                    }
                    $scope.AddToCache();
                });

            }, function () {
                r = "You pressed Cancel!";
            });

        }
