        $scope.deletecolorvision = function (eye, Item) {

            // 🔥 NORMALIZE FUNCTION (for duplicate fix)
            function normalizeText(txt) {
                return (txt || "")
                    .replace(/\s+/g, ' ')
                    .trim()
                    .toLowerCase();
            }

            // 🔥 FORMAT FUNCTION (skip empty items)
            function formatCV(arr) {
                let desc = "";

                arr.forEach(item => {

                    // ✅ skip empty items (important)
                    if (!item.RightEyeRemarks && !item.LeftEyeRemarks && !item.Notes) return;

                    let txt = "";

                    if (item.RightEyeRemarks) txt += `OD : ${item.RightEyeRemarks}`;
                    if (item.LeftEyeRemarks) txt += `\nOS : ${item.LeftEyeRemarks}`;
                    if (item.Notes) txt += `\nNotes : ${item.Notes}`;

                    desc += `${item.InvestigationDesc}\n${txt}\n\n`;
                });

                return desc.trim();
            }

            // ✅ STEP 1: OLD DATA
            let oldArr = angular.copy($scope.cacheStorageItem.ColorVisionDetails || []);
            let oldDesc = formatCV(oldArr);

            // ================= DELETE LOGIC =================
            if (eye === "OD") {
                Item.RS3Url = "";
                Item.IsRS3Url = false;
                Item.RightEyeRemarks = "";
            }
            if (eye === "OS") {
                Item.LS3Url = "";
                Item.IsLS3Url = false;
                Item.LeftEyeRemarks = "";
            }
            if (eye === "R") {
                Item.RightEyeRemarks = "";
            }
            if (eye === "L") {
                Item.LeftEyeRemarks = "";
            }

            if (eye == "R" || eye == "L") {
                if (Item.RightEyeRemarks == "" && Item.LeftEyeRemarks == "") {
                    Item.Notes = "";
                }
            }

            if (eye === "OS" || eye === "OD") {
                if (Item.RightEyeRemarks == "" && Item.LeftEyeRemarks == "" &&
                    Item.RS3Url == "" && Item.LS3Url == "") {
                    Item.Notes = "";
                }
            }

            if (Item.LS3Url == "" && Item.RS3Url == "" &&
                Item.RightEyeRemarks === "" && Item.LeftEyeRemarks == "" && Item.Notes == "") {
                Item.ActiveInd = 'N';
            }

            // ✅ STEP 2: NEW DATA
            let newArr = angular.copy($scope.cacheStorageItem.ColorVisionDetails || []);
            let newDesc = formatCV(newArr);

            let ScreenType = "Colour Vision Test";

            // 🔥 STEP 3: DUPLICATE CHECK (FINAL FIX)
            let alreadyExists = ($scope.LogObj.LogArray || []).some(x =>
                x.ScreenType === ScreenType &&
                x.ActionType === "Edited" &&
                normalizeText(x.OldActionDescription) === normalizeText(oldDesc) &&
                normalizeText(x.NewActionDescription) === normalizeText(newDesc)
            );

            // ✅ STEP 4: PUSH LOG
            if (oldDesc !== newDesc && !alreadyExists) {

                $scope.LogObj.LogArray.push({
                    LogId: 0,
                    ModuleId: 1,
                    ModuleName: "OUTPatient",
                    SubModuleId: 52,
                    SubModuleName: "Examination",
                    ScreenType: ScreenType,
                    ActionType: "Edited",
                    OldActionDescription: oldDesc,
                    NewActionDescription: newDesc,
                    ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss"),
                });
            }

            // ✅ STEP 5: API CALL
            var obj = {
                HospitalId: $scope.HospitalId,
                UserId: $scope.UserId,
                PatientId: $scope.cacheStorageItem.patientid,
                AppointmentId: $scope.cacheStorageItem.appointmentid,
                ColorVisionDetails: $scope.cacheStorageItem.ColorVisionDetails || [],
                VisitId: $scope.cacheStorageItem.PatientVisitId || 0,
                Logs: $scope.LogObj
            };

            eHnoteDiagnosisDataServices.AddupdateExaminationsData(obj).then(function (response) {

                if (response.data.data.Status === 'Success' || response.data.Message === "Success") {

                    angular.forEach($scope.cacheStorageItem.ColorVisionDetails, function (item) {

                        if ([14, 15, 16, 17].includes(item.InvestigationId) && item.ActiveInd == 'N') {
                            item.ActiveInd = 'Y';
                        }

                        $scope.AddToCache();
                    });
                }
            });
        };

        $scope.DeleteHealthConcernData = function (item) {
            $scope.LogObj.LogArray = [];
            var r = alertify.confirm("<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre'>Are You Sure To Delete The Patient Health Concern Data ? </h4>", function () {
                let dltcount = 0;
                let dltallergyNames = '';
                let date = '';
                var ConcernObj = {
                    "HospitalId": $scope.HospitalId,
                    "UserId": $scope.UserId,
                    "PatientId": $scope.cacheStorageItem.patientid,
                    "VisitId": $scope.cacheStorageItem.PatientVisitId,
                    "AppointmentID": $scope.cacheStorageItem.appointmentid,
                    "PatientHealthConcerns": [],
                    "AllergyRemarks": $scope.cacheStorageItem.AllergyRemarks || "",
                    "SurgicalRemarks": $scope.cacheStorageItem.SurgicalRemarks || "",
                    "CurrentSystemicRemarks": $scope.cacheStorageItem.CurrentSystemicRemarks || "",
                    "CurrentEyeRemarks": $scope.cacheStorageItem.CurrentEyeRemarks || "",
                    "SystemicHistoryRemarks": $scope.cacheStorageItem.SystemicHistoryRemarks || "",
                    "OccularHistoryRemarks": $scope.cacheStorageItem.OccularHistoryRemarks || "",
                    "OcularSurgicalHistoryRemarks": $scope.cacheStorageItem.OcularSurgicalHistoryRemarks || "",
                    "FamilyHistoryRemarks": $scope.cacheStorageItem.FamilyHistoryRemarks || "",
                    "FunctionalStatusRemarks": $scope.cacheStorageItem.FunctionalStatusRemarks || "",
                    "VaccinationHistoryRemarks": $scope.cacheStorageItem.VaccinationHistoryRemarks || "",
                    "BirthHistoryRemarks": $scope.cacheStorageItem.BirthHistoryRemarks || "",
                    "NutritionalHistoryRemarks": $scope.cacheStorageItem.NutritionalHistoryRemarks || "",
                    "MenstrualHistoryRemarks": $scope.cacheStorageItem.MenstrualHistoryRemarks || "",
                    "PhysicalEvaluationRemarks": $scope.cacheStorageItem.PhysicalEvaluationRemarks || "",
                    "PsychiatryRemarks": $scope.cacheStorageItem.PsychiatryRemarks || "",
                    "HealthGoalsRemarks": $scope.cacheStorageItem.HealthGoalsRemarks || "",
                    "LabInvestigationsRemarks": $scope.cacheStorageItem.LabInvestigationsRemarks || "",
                    "ImplantRemarks": $scope.cacheStorageItem.ImplantRemarks || "",
                    "PsychologicalObservRemarks": $scope.cacheStorageItem.PsychologicalObservRemarks || "",
                    "VitalsRemarks": $scope.cacheStorageItem.VitalsRemarks || "",
                    "LifestyleHistoryRemarks": $scope.cacheStorageItem.LifestyleHistoryRemarks || "",
                    "Logs": {},
                }
                item.DeleteInd = 'Y';
                ConcernObj.PatientHealthConcerns.push(item);

                if (item.DeleteInd === 'Y') {
                    if (dltcount > 0) dltallergyNames += ', ';
                    item.OnSetDate = item.OnSetDate || ''
                    if (item.OnSetDate != '') {
                        date = $filter('date')(item.OnSetDate, 'MM-dd-yyyy');
                    }
                    if (item.HealthConcernDescription) dltallergyNames += ('Discreption :' + item.HealthConcernDescription);
                    if (item.ExpressedBy) dltallergyNames += (' Expressed By :' + item.ExpressedBy);
                    if (date) dltallergyNames += (' OnSet :' + date);
                    if (item.Status) dltallergyNames += (' Status :' + item.Status);
                    dltcount++;
                }
                if (dltcount > 0) {
                    let description = (dltcount >0)
                        ? `Health Concerns - ${dltallergyNames.toUpperCase()}`
                        :'';

                    let obj = {
                        "LogId": 0,
                        "ModuleId": 1,
                        "ModuleName": "OUTPatient",
                        "SubModuleId": 48,
                        "SubModuleName": "ROS",
                        "ScreenType": "ROS(Health Concerns & Goals)",
                        "ActionType": "Deleted",
                        "OldActionDescription": description,
                        "NewActionDescription": '',
                        "ActionDateTime": $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss"),
                    };
                    $scope.LogObj.LogArray.push(obj);
                }
                if ($scope.LogObj.LogArray.length > 0) {
                    ConcernObj.Logs = $scope.LogObj || {};
                }
                eHnoteDiagnosisDataServices.AddupdateROSData(ConcernObj).then(function (response) {
                    if (response.data.Status === 'Success') {
                        alertify.success("Health Concern Deleted successfully!");
                    }
                    $scope.AddToCache();
                });

            }, function () {
                r = "You pressed Cancel!";
            });
        }

