        $scope.RemoveAssessmentPlan = function (item, type) {
            $scope.LogObj.LogArray = [];
            if (type == 'GonioscopyProvisional') {
              
             //   let deletedList = [];
                let deletedCount = 0;
                let AssesmentNames = '';
                var obj = {
                    "AssessmentPlanId": item.AssessmentPlan.AssessmentPlanId,
                    "ConsultationDiagnosisId": item.ConsultationDiagnosisId,
                    "DeleteInd": 'Y',
                    "PatientId": $scope.cacheStorageItem.patientid,
                    "AppointmentId": $scope.cacheStorageItem.appointmentid,
                    "UserId": $scope.UserId || 0,
                    "HospitalId": $scope.HospitalID,
                    "Logs":{},

                }
                if (obj.DeleteInd === 'Y') {
                    let CodeSystem = item.CodeSystem ? item.CodeSystem + " - " : "";
                    let ICD10CODE = item.ICD10CODE ? item.ICD10CODE + " | " : "";

                    if (deletedCount > 0) AssesmentNames += ', ';
                    AssesmentNames += `${CodeSystem}${ICD10CODE}${item.DiagnosisName}`;
                    deletedCount++;
                }
                if (deletedCount > 0) {
                    $scope.LogObj.LogArray.push({
                        LogId: 0,
                        ModuleId: 1,
                        ModuleName: "OUTPatient",
                        SubModuleId: 53,
                        SubModuleName: "Assessment Plan",
                        ScreenType: "Assessment(Summary)",
                        ActionType: "Deleted",
                        OldActionDescription: AssesmentNames,
                        NewActionDescription: "",
                        ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
                    });
                }
                if ($scope.LogObj.LogArray.length > 0) {
                    obj.Logs = $scope.LogObj || {};
                }
                eHnoteDiagnosisDataServices.DeleteAssessmentPlanData(obj).then(function (response) {

                    if (response.data.Status === 'Success') {
                        var index = $scope.cacheStorageItem.AssessmentPlan.indexOf(item);
                        if (index > -1) {
                            $scope.cacheStorageItem.AssessmentPlan.splice(index, 1);
                            $scope.AddToCache();
                        }

                        if (item.InvestigationsArray.length > 0) {
                            angular.forEach(item.InvestigationsArray, function (aitem) {
                                if ($scope.cacheStorageItem.InvestigationsDetails.length > 0) {
                                    angular.forEach($scope.cacheStorageItem.InvestigationsDetails, function (bitem) {
                                        if (aitem.InvestigationId == bitem.DescriptionId) {
                                            bitem.DeleteInd = 'Y';
                                        }
                                    });
                                }

                            });
                        }
                        if (item.ProceduresArray.length > 0) {
                            angular.forEach(item.ProceduresArray, function (aitem) {
                                if ($scope.cacheStorageItem.ProceduresDetails.length > 0) {
                                    angular.forEach($scope.cacheStorageItem.ProceduresDetails, function (bitem) {
                                        if (aitem.ProcedureId == bitem.DescriptionId) {
                                            bitem.DeleteInd = 'Y';
                                        }
                                    });
                                }

                            });
                        }
                        if (item.SurgeryArray.length > 0) {
                            angular.forEach(item.SurgeryArray, function (aitem) {
                                if ($scope.cacheStorageItem.SurgeriesDetails.length > 0) {
                                    angular.forEach($scope.cacheStorageItem.SurgeriesDetails, function (bitem) {
                                        if (aitem.SurgeryId == bitem.DescriptionId) {
                                            bitem.DeleteInd = 'Y';
                                        }
                                    });
                                }

                            });
                        }


                        $scope.AddToCache();
                    }
                });
            } else {
                var r = alertify.confirm("<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre'>Are you sure you want to Delete ? </h4>", function () {
                    
                    let deletedCount = 0;
                    let AssesmentNames = '';
                   // deletedList.push(formatAssessmentLine(item, masters));
                  /*  deletedCount++;*/
                    var obj = {
                        "AssessmentPlanId": item.AssessmentPlan.AssessmentPlanId,
                        "ConsultationDiagnosisId": item.ConsultationDiagnosisId,
                        "DeleteInd": 'Y',
                        "PatientId": $scope.cacheStorageItem.patientid,
                        "AppointmentId": $scope.cacheStorageItem.appointmentid,
                        "UserId": $scope.UserId || 0,
                        "HospitalId": $scope.HospitalID,
                        "Logs":{},

                    }
                    if (obj.DeleteInd === 'Y') {
                        let CodeSystem = item.CodeSystem ? item.CodeSystem + " - " : "";
                        let ICD10CODE = item.ICD10CODE ? item.ICD10CODE + " | " : "";

                        if (deletedCount > 0) AssesmentNames += ', ';
                        AssesmentNames += `${CodeSystem}${ICD10CODE}${item.DiagnosisName}` ;
                        deletedCount++;
                    }
                    if (deletedCount > 0) {
                        $scope.LogObj.LogArray.push({
                            LogId: 0,
                            ModuleId: 1,
                            ModuleName: "OUTPatient",
                            SubModuleId: 53,
                            SubModuleName: "Assessment Plan",
                            ScreenType: "Assessment(Summary)",
                            ActionType: "Deleted",
                            OldActionDescription: AssesmentNames,
                            NewActionDescription: "",
                            ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
                        });
                    }
                    if ($scope.LogObj.LogArray.length > 0) {
                        obj.Logs = $scope.LogObj || {};
                    }
                    eHnoteDiagnosisDataServices.DeleteAssessmentPlanData(obj).then(function (response) {

                        if (response.data.Status === 'Success') {
                            if (item.DiagnosisId == 2) {
                                var index = $scope.cacheStorageItem.AssessmentPlan.indexOf(item);
                                var List = $filter("filter")($scope.cacheStorageItem.GeneralAssessmentPlan, { "ConsultationDiagnosisId": item.ConsultationDiagnosisId }, true) || [];
                                if (index > -1) {
                                    if (item.ConsultationDiagnosisId == 0) {
                                        $scope.cacheStorageItem.AssessmentPlan.splice(index, 1);
                                    } else {
                                        $scope.cacheStorageItem.AssessmentPlan[index].DeleteInd = 'Y';
                                        $scope.cacheStorageItem.AssessmentPlan[index].AssessmentPlan.DeleteInd = 'Y';
                                    }
                                }
                                if (List.length > 0) {
                                    angular.forEach(List, function (rgitem) {
                                        if (rgitem.ConsultationDiagnosisId !== 0) {
                                            var indexToRemove = $scope.cacheStorageItem.GeneralAssessmentPlan.indexOf(rgitem);
                                            if (indexToRemove !== -1) {
                                                $scope.cacheStorageItem.GeneralAssessmentPlan.splice(indexToRemove, 1);
                                            }
                                        }

                                    });
                                }
                                $scope.AddToCache();
                            } else {
                                var index = $scope.cacheStorageItem.AssessmentPlan.indexOf(item);
                                if (index > -1) {
                                    if (item.ConsultationDiagnosisId == 0) {
                                        $scope.cacheStorageItem.AssessmentPlan.splice(index, 1);
                                    } else {
                                        $scope.cacheStorageItem.AssessmentPlan[index].DeleteInd = 'Y';
                                        $scope.cacheStorageItem.AssessmentPlan[index].AssessmentPlan.DeleteInd = 'Y';
                                    }
                                    $scope.cacheStorageItem.SquintPossibleDiagnosis = "";
                                    $scope.cacheStorageItem.SquintPossibleDiagnosisId = 0;
                                    $scope.cacheStorageItem.BVPossibleDiagnosis = "";
                                    $scope.cacheStorageItem.BVPossibleDiagnosisId = 0;
                                    $scope.AddToCache();
                                }

                                if (item.InvestigationsArray.length > 0) {
                                    angular.forEach(item.InvestigationsArray, function (aitem) {
                                        if ($scope.cacheStorageItem.InvestigationsDetails.length > 0) {
                                            angular.forEach($scope.cacheStorageItem.InvestigationsDetails, function (bitem) {
                                                if (aitem.InvestigationId == bitem.DescriptionId) {
                                                    bitem.DeleteInd = 'Y';
                                                }
                                            });
                                        }

                                    });
                                }
                                if (item.ProceduresArray.length > 0) {
                                    angular.forEach(item.ProceduresArray, function (aitem) {
                                        if ($scope.cacheStorageItem.ProceduresDetails.length > 0) {
                                            angular.forEach($scope.cacheStorageItem.ProceduresDetails, function (bitem) {
                                                if (aitem.ProcedureId == bitem.DescriptionId) {
                                                    bitem.DeleteInd = 'Y';
                                                }
                                            });
                                        }

                                    });
                                }
                                if (item.SurgeryArray.length > 0) {
                                    angular.forEach(item.SurgeryArray, function (aitem) {
                                        if ($scope.cacheStorageItem.SurgeriesDetails.length > 0) {
                                            angular.forEach($scope.cacheStorageItem.SurgeriesDetails, function (bitem) {
                                                if (aitem.SurgeryId == bitem.DescriptionId) {
                                                    bitem.DeleteInd = 'Y';
                                                }
                                            });
                                        }

                                    });
                                }

                                if (item.CodeSystem == "Snomed-CT") {
                                    var obj = {
                                        "Deleted": 'y',
                                        "Status": 'Deleted',
                                        //"DiagnosisStatusId": 7,
                                        "RcopiaProblemId": item.RcopiaProblemId || "",
                                        "OnsetDate": $filter('date')(new Date(), "MM-dd-yyyy h:mm a"),
                                        "RcopiaID": item.RcopiaProblemId || "",
                                        "ExternalID": item.ConsultationDiagnosisId, //item.DiagnosisId
                                        "IsIcd11": false,
                                        "IsIcd10": false,
                                        "IsIcd9": false,
                                        "IsSnomedCode": true,
                                        "DiagnosisCode": '',
                                        "DiagnosisName": '',
                                        "SnomedConceptID": item.ICD10CODE || '',
                                        "SnomedDescription": item.ICD10DIAGNAME,
                                    };
                                }
                                else {
                                    var obj = {
                                        "Deleted": 'y',
                                        "Status": 'Deleted',
                                        //"DiagnosisStatusId": 7,
                                        "RcopiaProblemId": item.RcopiaProblemId || "",
                                        "OnsetDate": $filter('date')(new Date(), "MM-dd-yyyy h:mm a"),
                                        "RcopiaID": item.RcopiaProblemId || "",
                                        "ExternalID": item.ConsultationDiagnosisId, //item.DiagnosisId
                                        "IsIcd11": false,
                                        "IsIcd10": true,
                                        "IsIcd9": false,
                                        "IsSnomedCode": item.SnomedCode || '',
                                        "DiagnosisCode": item.ICD10CODE || '', //ICD10CODE olny
                                        "DiagnosisName": item.ICD10DIAGNAME,
                                        "SnomedConceptID": '',
                                        "SnomedDescription": '',

                                    };
                                }
                                $scope.addUpdatePatientProblemsToRcopiaReqObj.DiagnosisList.push(obj);

                                console.log($scope.addUpdatePatientProblemsToRcopiaReqObj);
                                $scope.addUpdatePatientProblemsToRcopiaReqObj.OrganizationId = $scope.HospitalID;

                                eHnoteDiagnosisDataServices.addPatientProblemToRcopia($scope.addUpdatePatientProblemsToRcopiaReqObj).then(function (response) {



                                    if (response.data.status === 'Success') {

                                    }



                                });
                                $scope.AddToCache();
                            }
                        }
                    });
                }, function () {
                    r = "You pressed Cancel!";
                });
            }
        };
