        $scope.formatGonioscopyDesc = function (item, type) {
            type = type || "";
            if (!item) return '';
            let desc = '';

            if (type == "OD") {
                if (item.RightEye) {
                    let fields = [
                        "DepthRightValue", "RightValue", "DepthLeftValue", "LeftValue",
                        "DepthBottomValue", "BottomValue", "DepthTopValue", "TopValue", "PigmentValue"
                    ];
                    desc += 'OD - ';
                    desc += fields.map(f => `${f}:${item.RightEye[f] || ''}`).join(', ');
                    // ✅ RightEyeRemarks
                    if (item.RightEyeRemarks) desc += `, Remarks: ${item.RightEyeRemarks}`;
                    if (item.RightEye.RightEyePossibleDiagnosisArray && item.RightEye.RightEyePossibleDiagnosisArray.length > 0) {
                        let diag = item.RightEye.RightEyePossibleDiagnosisArray
                            .filter(d => d.DeleteInd === 'N')
                            .map(d => `${d.ICD10CODE}-${d.PossibleDiagnosisName}`);
                        if (diag.length > 0) desc += ` | ODPossibleDiagnosis: ${diag.join(', ')}`;
                    }
                    desc += '\n';
                }
            } else if (type == "OS") {
                if (item.LeftEye) {
                    let fields = [
                        "DepthRightValue", "RightValue", "DepthLeftValue", "LeftValue",
                        "DepthBottomValue", "BottomValue", "DepthTopValue", "TopValue", "PigmentValue"
                    ];
                    desc += 'OS - ';
                    desc += fields.map(f => `${f}:${item.LeftEye[f] || ''}`).join(', ');
                    // ✅ LeftEyeRemarks
                    if (item.LeftEyeRemarks) desc += `, Remarks: ${item.LeftEyeRemarks}`;
                    if (item.LeftEye.LeftEyePossibleDiagnosisArray && item.LeftEye.LeftEyePossibleDiagnosisArray.length > 0) {
                        let diag = item.LeftEye.LeftEyePossibleDiagnosisArray
                            .filter(d => d.DeleteInd === 'N')
                            .map(d => `${d.ICD10CODE}-${d.PossibleDiagnosisName}`);
                        if (diag.length > 0) desc += ` | OSPossibleDiagnosis: ${diag.join(', ')}`;
                    }
                }
            } else {
                // OD
                if (item.RightEye) {
                    let fields = [
                        "DepthRightValue", "RightValue", "DepthLeftValue", "LeftValue",
                        "DepthBottomValue", "BottomValue", "DepthTopValue", "TopValue", "PigmentValue"
                    ];
                    desc += 'OD - ';
                    desc += fields.map(f => `${f}:${item.RightEye[f] || ''}`).join(', ');
                    // ✅ RightEyeRemarks
                    if (item.RightEyeRemarks) desc += `, Remarks: ${item.RightEyeRemarks}`;
                    if (item.RightEye.RightEyePossibleDiagnosisArray && item.RightEye.RightEyePossibleDiagnosisArray.length > 0) {
                        let diag = item.RightEye.RightEyePossibleDiagnosisArray
                            .filter(d => d.DeleteInd === 'N')
                            .map(d => `${d.ICD10CODE}-${d.PossibleDiagnosisName}`);
                        if (diag.length > 0) desc += ` | ODPossibleDiagnosis: ${diag.join(', ')}`;
                    }
                    desc += '\n';
                }
                // OS
                if (item.LeftEye) {
                    let fields = [
                        "DepthRightValue", "RightValue", "DepthLeftValue", "LeftValue",
                        "DepthBottomValue", "BottomValue", "DepthTopValue", "TopValue", "PigmentValue"
                    ];
                    desc += 'OS - ';
                    desc += fields.map(f => `${f}:${item.LeftEye[f] || ''}`).join(', ');
                    // ✅ LeftEyeRemarks
                    if (item.LeftEyeRemarks) desc += `, Remarks: ${item.LeftEyeRemarks}`;
                    if (item.LeftEye.LeftEyePossibleDiagnosisArray && item.LeftEye.LeftEyePossibleDiagnosisArray.length > 0) {
                        let diag = item.LeftEye.LeftEyePossibleDiagnosisArray
                            .filter(d => d.DeleteInd === 'N')
                            .map(d => `${d.ICD10CODE}-${d.PossibleDiagnosisName}`);
                        if (diag.length > 0) desc += ` | OSPossibleDiagnosis: ${diag.join(', ')}`;
                    }
                }
            }

            return desc.trim();
        };


        $scope.RemoveGonioscopyDetails = function (item) {
            var tempPossibleDiagnosisArray = angular.copy(item);
            var r = alertify.confirm("<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre'>Are You Sure Want To Delete ?  </h4>", function () {
                $scope.LogObj.LogArray = [];
                var Isrightpossdign = false, Isleftpossdign = false;

                // ✅ Old data save - before clearing
                let gonioscopyItem = $scope.cacheStorageItem.GonioscopyDetails.find(function (x) { return x.InvestigationId == 2127; });
                let oldDesc = gonioscopyItem ? $scope.formatGonioscopyDesc(gonioscopyItem, "") : '';

                // ✅ Log push - before API call (like RemoveRos pattern)
                if (oldDesc) {
                    let log = {
                        "LogId": 0,
                        "ModuleId": 1,
                        "ModuleName": "OUTPatient",
                        "SubModuleId": 52,
                        "SubModuleName": "Examination",
                        "ScreenType": "Gonioscopy",
                        "ActionType": "Deleted",
                        "OldActionDescription": oldDesc,
                        "NewActionDescription": '',
                        "ActionDateTime": $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
                    };
                    $scope.LogObj.LogArray.push(log);
                }

                angular.forEach($scope.cacheStorageItem.GonioscopyDetails, function (item) {
                    if (item.InvestigationId == 2127) {
                        item.InvestigationOrgans = [];
                        item.RightEyeRemarks = '';
                        item.RightEyeEdit = true;
                        item.RightEye.RightValue = "";
                        item.RightEye.LeftValue = "";
                        item.RightEye.TopValue = "";
                        item.RightEye.BottomValue = "";
                        item.RightEye.Remarks = "";
                        item.RightEye.ImagesArray = "";
                        item.RightEye.CdRatio = "";
                        item.RightEye.Frequency = "";
                        item.RightEye.PigmentValue = "";
                        item.RightEye.RightValueObj = "";
                        item.RightEye.LeftValueObj = "";
                        item.RightEye.TopValueObj = "";
                        item.RightEye.BottomValueObj = "";
                        item.RightEye.PigmentValueObj = "";
                        item.RightEye.DepthRightValue = "";
                        item.RightEye.DepthLeftValue = "";
                        item.RightEye.DepthTopValue = "";
                        item.RightEye.DepthBottomValue = "";
                        item.InvestigationOrgans = [];
                        item.LeftEyeRemarks = '';
                        item.LeftEyeEdit = true;
                        item.LeftEye.RightValue = "";
                        item.LeftEye.LeftValue = "";
                        item.LeftEye.TopValue = "";
                        item.LeftEye.BottomValue = "";
                        item.LeftEye.Remarks = "";
                        item.LeftEye.ImagesArray = "";
                        item.LeftEye.CdRatio = "";
                        item.LeftEye.Frequency = "";
                        item.LeftEye.PigmentValue = "";
                        item.LeftEye.RightValueObj = "";
                        item.LeftEye.LeftValueObj = "";
                        item.LeftEye.TopValueObj = "";
                        item.LeftEye.BottomValueObj = "";
                        item.LeftEye.PigmentValueObj = "";
                        item.LeftEye.DepthRightValue = "";
                        item.LeftEye.DepthLeftValue = "";
                        item.LeftEye.DepthTopValue = "";
                        item.LeftEye.DepthBottomValue = "";
                        if (item.RightEye.RightEyePossibleDiagnosisArray.length > 0) {
                            angular.forEach(item.RightEye.RightEyePossibleDiagnosisArray, function (mitem) {
                                mitem.DeleteInd = 'Y';
                                Isrightpossdign = true;
                            });
                        }
                        if (item.LeftEye.LeftEyePossibleDiagnosisArray.length > 0) {
                            angular.forEach(item.LeftEye.LeftEyePossibleDiagnosisArray, function (mitem) {
                                mitem.DeleteInd = 'Y';
                                Isleftpossdign = true;
                            });
                        }

                        if (item.RightEye.RightValue == '' && item.RightEye.LeftValue == '' && item.RightEye.TopValue == '' && item.RightEye.BottomValue == '' && item.RightEye.PigmentValue == '' && item.RightEyeRemarks == '' && item.RightEye.DepthRightValue == '' && item.RightEye.DepthLeftValue == '' && item.RightEye.DepthTopValue == '' && item.RightEye.DepthBottomValue == '' &&
                            item.LeftEye.RightValue == '' && item.LeftEye.LeftValue == '' && item.LeftEye.TopValue == '' && item.LeftEye.BottomValue == '' && item.LeftEye.PigmentValue == '' && item.LeftEyeRemarks == '' && item.LeftEye.DepthRightValue == '' && item.LeftEye.DepthLeftValue == '' && item.LeftEye.DepthTopValue == '' && item.LeftEye.DepthBottomValue == '' && Isleftpossdign == true && Isrightpossdign == true) {
                            item.ActiveInd = 'N';
                        }
                    }
                });

                var obj = {
                    "HospitalId": $scope.HospitalId,
                    "UserId": $scope.UserId,
                    "PatientId": $scope.cacheStorageItem.patientid,
                    "AppointmentId": $scope.cacheStorageItem.appointmentid,
                    "GonioscopyDetails": $scope.cacheStorageItem.GonioscopyDetails || [],
                    "VisitId": $scope.cacheStorageItem.PatientVisitId || 0,
                };

                // ✅ RemoveRos pattern - Logs obj కి attach చేయండి
                if ($scope.LogObj.LogArray.length > 0) {
                    obj.Logs = $scope.LogObj || {};
                }

                eHnoteDiagnosisDataServices.AddupdateExaminationsData(obj).then(function (response) {
                    if (response.data.data.Status === 'Success') {

                        angular.forEach($scope.cacheStorageItem.GonioscopyDetails, function (Gitem) {
                            Gitem.IsInvDataAdded = false;
                            Gitem.ActiveInd = 'Y';
                        });

                        if (tempPossibleDiagnosisArray.length > 0) {
                            angular.forEach(tempPossibleDiagnosisArray, function (Gitem) {
                                $scope.cacheStorageItem.AssessmentPlan = $scope.cacheStorageItem.AssessmentPlan || [];
                                if ($scope.cacheStorageItem.AssessmentPlan.length > 0) {
                                    var filterRtdiagnosis = [];
                                    var filterLtdiagnosis = [];
                                    filterRtdiagnosis = $filter("filter")($scope.cacheStorageItem.AssessmentPlan, { "DiagnosisId": Gitem.RightEye.PossibleDiagnosisId, "DeleteInd": "N" }, true) || [];
                                    if (filterRtdiagnosis.length > 0) {
                                        $scope.RemoveAssessmentPlan(filterRtdiagnosis[0], "GonioscopyProvisional");
                                    }
                                    filterLtdiagnosis = $filter("filter")($scope.cacheStorageItem.AssessmentPlan, { "DiagnosisId": Gitem.LeftEye.PossibleDiagnosisId, "DeleteInd": "N" }, true) || [];
                                    if (filterLtdiagnosis.length > 0) {
                                        $scope.RemoveAssessmentPlan(filterLtdiagnosis[0], "GonioscopyProvisional");
                                    }
                                }
                            });
                        }
                    }
                });
            }, function () {
                r = "You pressed Cancel!";
            });
        };
