                            "GenericName": pitem.DrugGenericName,
                            "Form": pitem.DrugForm,
                            "Schedule": scheduletype,
                            "Strength": pitem.DrugStrength,
                            "Supply": "n",
                            "Compound": "n",
                            "Action": pitem.Action,
                            "Dose": pitem.Dose,
                            "Route": pitem.Route,
                            "DoseUnit": pitem.DoseUnit,
                            "DoseTiming": pitem.Frequency,
                            "DoseOther": pitem.DoseOther,
