        $scope.deleteRightMRDvalues = function (inv) {
            $scope.LogObj.LogArray=[];
            let odHas =
                inv.RMRD1 || inv.RMRD2 || inv.RMRDcNS || inv.RLF || inv.RPFH;

            let deleteLog = "";

            if (odHas) {
                let parts = [];

                if (inv.RMRD1) parts.push(`MRD1: ${inv.RMRD1}`);
                if (inv.RMRDcNS) parts.push(`MRDcNS: ${inv.RMRDcNS}`);
                if (inv.RMRD2) parts.push(`MRD2: ${inv.RMRD2}`);
                if (inv.RLF) parts.push(`LF: ${inv.RLF}`);
                if (inv.RPFH) parts.push(`PFH: ${inv.RPFH}`);

                deleteLog =
                    `MRD - Marginal Reflex Distance :
                  OD (Right Eye) - ${parts.join(", ")}`;
            }
            inv.RLF = "";
            inv.RMRD1 = "";
            inv.RMRD2 = "";
            inv.RMRDcNS = "";
            inv.RPFH = "";
            if (inv.RLF === "" && inv.RMRD1 === "" && inv.RMRD2 === "" && inv.RMRDcNS === "" && inv.RPFH === "" &&
                inv.LLF === "" && inv.LMRD1 === "" && inv.LMRD2 === "" && inv.LMRDcNS === "" && inv.LPFH === "") {
                inv.ActiveInd = 'N';
            }

            if (deleteLog.trim() !== "") {
                $scope.LogObj.LogArray.push({
                    LogId: 0,
                    ModuleId: 1,
                    ModuleName: "OUTPatient",
                    SubModuleId: 52,
                    SubModuleName: "Examination",
                    ScreenType: "Anterior Segment from Summary",
                    ActionType: "Deleted",
                    OldActionDescription: `${deleteLog}`,
                    NewActionDescription: "",
                    ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
                });
            }
            var obj = {
                "HospitalId": $scope.HospitalId,
                "UserId": $scope.UserId,
                "PatientId": $scope.cacheStorageItem.patientid,
                "AppointmentId": $scope.cacheStorageItem.appointmentid,
                "AnteriorSegmentArrayNew": $scope.cacheStorageItem.AnteriorSegmentArrayNew || [],
                "VisitId": $scope.cacheStorageItem.PatientVisitId || 0,
                "Logs":{}
            }
            if ($scope.LogObj.LogArray.length > 0) {
                obj.Logs = $scope.LogObj || {};
            }
            eHnoteDiagnosisDataServices.AddupdateExaminationsData(obj).then(function (response) {
                if (response.data.data.Status === 'Success') {
                    angular.forEach($scope.cacheStorageItem.AnteriorSegmentArrayNew, function (item, index) {
                        if (item.ActiveInd == 'N') {
                            $scope.cacheStorageItem.AnteriorSegmentArrayNew.splice(index, 1);
                        }
                        $scope.AddToCache();
                    });
                    //if ($scope.cacheStorageItem.AnteriorSegmentArrayNew.length > 0) {
                    //    angular.forEach($scope.cacheStorageItem.AnteriorSegmentArrayNew, function (citem) {
                    //        if (citem.ActiveInd == 'Y' && citem.InvestigationId == 6) {
                    //            /*$scope.CDRarray.push(citem);*/
                    //        }
                    //    });
                    //}
                }
            });
        }
