        $scope.SaveCheifComplaintsData = function (citem) {
            $scope.LogObj.LogArray = [];
            $scope.cacheStorageItem.ChiefComplaints.forEach(citem => citem.IsDescriptionEdit = false);
            var CheifComplaitsobject = {
                "VisitId": $scope.cacheStorageItem.PatientVisitId,
                "AppointmentID": $scope.cacheStorageItem.appointmentid,
                "OrganizationId": $scope.HospitalId,
                "UserId": $scope.UserId,
                "ConsultationDate": $scope.cacheStorageItem.ConsultationDate || "",
                "ChiefComplaintNotes": $scope.cacheStorageItem.ChiefComplaints || [],
                "Logs": {},
                "HistoryOfPresentIllness": $scope.cacheStorageItem.HistoryOfPresentIllness || '',
            };
            if ($scope.LogObj.ChiefComplaints.length > 0) {

                let OldActionDescription = "";
                let NewActionDescription = "";
                let ActionType = "";
                let dltcount = 0;
                let dltNames = '';

                angular.forEach(CheifComplaitsobject.ChiefComplaintNotes, function (newItem) {
                    if (newItem.ActiveInd === 'N') {
                        if (dltcount > 0) dltNames += ', ';
                        dltNames += newItem.Description;
                        dltcount++;
                    } else {

                        let oldItem = $scope.LogObj.ChiefComplaints.find(x => x.PatientChiefComplaintId === newItem.PatientChiefComplaintId && newItem.ActiveInd=='Y');

                        if (oldItem) {
                            // Edited case
                            if (oldItem.Description !== newItem.Description) {
                                if (OldActionDescription !== "") OldActionDescription += "\n ";
                                if (NewActionDescription !== "") NewActionDescription += "\n ";

                                OldActionDescription += `${oldItem.Description || ""}`;
                                NewActionDescription += `${newItem.Description || ""}`;
                               
                            }
                        }

                    }
                });
                if (CheifComplaitsobject.HistoryOfPresentIllness != "" || $scope.LogObj.HistoryOfPresentIllness != '') {
                    if (CheifComplaitsobject.HistoryOfPresentIllness != $scope.LogObj.HistoryOfPresentIllness) {
                        if (CheifComplaitsobject.HistoryOfPresentIllness)
                            NewActionDescription += `${NewActionDescription ? '\n ' : ''}HPI : ${CheifComplaitsobject.HistoryOfPresentIllness}`;
                        if ($scope.LogObj.HistoryOfPresentIllness)
                            OldActionDescription += `${OldActionDescription ? '\n' : ''}HPI : ${$scope.LogObj.HistoryOfPresentIllness}`;
                    }
                }
                ActionType = "Edited";
                if (OldActionDescription !== "" || NewActionDescription !== "") {
                    let obj = {
                        "LogId": 0,
                        "ModuleId": 1,
                        "ModuleName": "OUTPatient",
                        "SubModuleId": 47,
                        "SubModuleName": "Chief Complaints",
                        "ScreenType": "Chief Complaints(Summary)",
                        "ActionType": ActionType,
                        "OldActionDescription": OldActionDescription,
                        "NewActionDescription": NewActionDescription,
                        "ActionDateTime": $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss"),
                    };
                    $scope.LogObj.LogArray.push(obj);
                }
                if (dltcount > 0) {
                    let obj = {
                        "LogId": 0,
                        "ModuleId": 1,
                        "ModuleName": "OUTPatient",
                        "SubModuleId": 47,
                        "SubModuleName": "Chief Complaints",
                        "ScreenType": "Chief Complaints(Summary)",
                        "ActionType": "Deleted",
                        "OldActionDescription": dltNames,
                        "NewActionDescription":"",
                        "ActionDateTime": $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss"),
                    };
                    $scope.LogObj.LogArray.push(obj);
                }


            } else if (CheifComplaitsobject.ChiefComplaintNotes.length > 0) {
                var ActionDescription = '';
                angular.forEach(CheifComplaitsobject.ChiefComplaintNotes, function (itemA) {

                    if (ActionDescription !== '') {
                        ActionDescription += '\n ';
                    }
                    ActionDescription += `${itemA.Description}`;


                });

                if (ActionDescription != '') {
                    let obj = {
                        "LogId": 0,
                        "ModuleId": 1,
                        "ModuleName": "OUTPatient",
                        "SubModuleId": 47,
                        "SubModuleName": "Chief Complaints",
                        "ScreenType": "Chief Complaints(Summary)",
                        "ActionType": "Added",
                        "OldActionDescription": "",
                        "NewActionDescription": ActionDescription,
                        "ActionDateTime": $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss"),
                    };
                    $scope.LogObj.LogArray.push(obj);
                }
            }

            if ($scope.LogObj.LogArray.length > 0) {
                CheifComplaitsobject.Logs = $scope.LogObj || {};
            }
            eHnoteDiagnosisDataServices.AddUpdateChiefComplaints(CheifComplaitsobject, true).then(function (resp) {
                if (resp.data.Status === 'Success') {
                    $scope.LogObj.ChiefComplaints = angular.copy($scope.cacheStorageItem.ChiefComplaints) || [];
                    $scope.LogObj.HistoryOfPresentIllness = angular.copy($scope.cacheStorageItem.HistoryOfPresentIllness) || [];
                    console.log(resp.data);
                }
            }, function (err) {
                alertify.error(err.data.ExceptionMessage);
            });
        };
        $scope.compareAssessmentList = function () {

            const newList = $scope.cacheStorageItem.AssessmentPlan || [];
            const oldList = $scope.LogObj.AssessmentPlan || [];


            let oldArr = [];
            let newArr = [];

            // ---------------------- HEADER ----------------------
            function header(item) {
                let cs = item.CodeSystem ? item.CodeSystem + " - " : "";
                let icd = item.ICD10CODE ? item.ICD10CODE + " | " : "";
                return `${cs}${icd}${item.DiagnosisName || item.ICD10DIAGDESCRIPTION}`;
            }

            // ---------------------- CHECK FIELD ----------------------
            function check(label, oldV, newV, oldFields, newFields) {
                if ((oldV || "") !== (newV || "")) {
                    if (oldV) oldFields.push(`${label} : ${oldV}`);
                    if (newV) newFields.push(`${label} : ${newV}`);
                }
            }

          
            newList.forEach(n => {

                if (n.DeleteInd == "Y") return;

                let old = oldList.find(o => o.ConsultationDiagnosisId == n.ConsultationDiagnosisId);

                let h = header(n);

                // ---------------------- EDITED ----------------------
                let oldF = [];
                let newF = [];

               
                // NOTES
                let op = old.AssessmentPlan || {};
                let np = n.AssessmentPlan || {};

                check("Assessment Notes", op.AssessmentsNotes, np.AssessmentsNotes, oldF, newF);
                check("Doctor Notes", op.DoctorNotes, np.DoctorNotes, oldF, newF);
                check("Plan", op.PlanofDiscussionsNotes, np.PlanofDiscussionsNotes, oldF, newF);
                check("Actions Taken", op.ActionsTaken, np.ActionsTaken, oldF, newF);
                check("Patient Instructions", op.PatientInstructions, np.PatientInstructions, oldF, newF);

                if (oldF.length || newF.length) {
                    oldArr.push(h + "\n" + oldF.join("\n"));
                    newArr.push(h + "\n" + newF.join("\n"));
                }
            });

          

            return {
                oldDescription: oldArr.join("\n\n").trim(),
                newDescription: newArr.join("\n\n").trim()
            };
        };

        $scope.updateAssessmentPlanDetails = function () {
            $scope.LogObj.LogArray=[];
            let obj = {
                "VisitId": $scope.cacheStorageItem.PatientVisitId,
                "AppointmentID": $scope.cacheStorageItem.appointmentid,
                "OrganizationId": $scope.HospitalId,
                "HospitalId": $scope.HospitalId,
                "UserId": $scope.UserId,
                "AssessmentplanArray": $scope.cacheStorageItem.AssessmentPlan || [],
                "Logs":{}
            }
            if ($scope.cacheStorageItem.AssessmentPlan && $scope.cacheStorageItem.AssessmentPlan.length > 0) {
                $scope.cacheStorageItem.AssessmentPlan.forEach(item => {
                    angular.forEach(item.editAssementObj, function (value, key) {
                        item.editAssementObj[key] = false;
                    });
                })
            }
            if ($scope.cacheStorageItem.AssessmentPlan.length > 0) {
                let result = $scope.compareAssessmentList();

                let actiontype = ($scope.LogObj.AssessmentPlan.length > 0 ? "Edited" : "Added");

                if (result.oldDescription || result.newDescription) {
                    $scope.LogObj.LogArray.push({
                        LogId: 0,
                        ModuleId: 1,
                        ModuleName: "OUTPatient",
                        SubModuleId: 53,
                        SubModuleName: "Assessment Plan",
                        ScreenType: "Assessment(Summary)",
                        ActionType: actiontype,
                        OldActionDescription: result.oldDescription,
                        NewActionDescription: result.newDescription,
                        ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
                    });
                }

            }
            if ($scope.LogObj.LogArray.length > 0) {
                obj.Logs = $scope.LogObj || {};
            }
            eHnoteDiagnosisDataServices.UpdateAssessmentDetails(obj, true).then(function (resp) {
                console.log(resp)
                if (resp.data.Status=="Success") {
                    $scope.LogObj.AssessmentPlan = angular.copy($scope.cacheStorageItem.AssessmentPlan)||[]
                }
            }, function (err) {
                alertify.error("Data Not Saved");
            })
        }
