        $scope.GetPatientNotesById = function () {
            var obj = {
                "PatientId": $scope.mainPatientProfileObj.PatientId || 0,
                "NoteTypeId": 6
            }
            eHnoteSettingsDataService.GetPatientNotesById(obj).then(function (resp) {
                if (resp.data.Status === "Success") {
                    $scope.RegisterPatientNotesArray = [];

                    resp.data.rows = resp.data.rows || [];
                    let AlertnotesArray = resp.data.rows;

                    if (AlertnotesArray.length > 0) {
                        angular.forEach(AlertnotesArray, function (citem) {
                            if (citem.AppointmentId == $scope.cacheStorageItem.appointmentid) {
                                $scope.RegisterPatientNotesArray.push(citem);
                            }
                        });
                        $scope.LogObj.RegisterPatientNotesArray = angular.copy($scope.RegisterPatientNotesArray)||[];
                    }


                } else {
                    alertify.error(resp.data.Message);
                }
            });
        }

