        $scope.NavToOpenStartVoiceChartingPopup = function (item) {
            var requestObj = {
                AppointmentId: item.AppointmentId || 0,
                PatientId: item.PatientId || 0,
                DoctorId: item.DoctorId || $scope.UserId,
                HospitalId: $scope.HospitalId || 0,
                UserId: $scope.UserId || 0,
                ConsultationId: item.VisitId,
                AmbientDomainUrl: "https://ambitious-flower-01bc6170f.7.azurestaticapps.net",
                PatientName: $scope.PatientDetailsInfo.FullName || "",
                DoctorName: $scope.DoctorName || "",
                ParentHospitalId: $scope.ParentHospitalId
            };

            eHnoteMainAppointmentService
                .GenerateAmbientSessionForVisit(requestObj)
                .then(function (resp) {
                    console.log(resp);

                    if (resp.data.Status !== "Success") {
                        alertify.error(resp.data.Message || "Failed");
                        return;
                    }

                    var API_URL = "https://app-ehnote-ai-api.azurewebsites.net";
                    var ambientBase = resp.data.AmbientUrl.replace(/\/$/, "");
                    var sessionToken = resp.data.SessionToken;

                    var ambientUrl = ambientBase + "/launch.html" +
                        "?token=" + encodeURIComponent(sessionToken) +
                        "&patient-id=" + encodeURIComponent(item.PatientID || "") +
                        "&doctor-id=" + encodeURIComponent(item.DoctorID || "") +
                        "&appointment-id=" + encodeURIComponent(item.AppointmentID || "") +
                        "&encounter-type=FollowUp" +
                        "&api-url=" + encodeURIComponent(API_URL) +
                        "&language=en-US";

                    console.log("Ambient URL:", ambientUrl);

                    var ambientWindow = window.open(

                        ambientUrl,

                        "ambient-console",

                        "width=430," +
                        "height=610," +
                        "resizable=no," +
                        "scrollbars=no," +
                        "location=no," +
                        "toolbar=no," +
                        "menubar=no," +
                        "status=no"

                    );

                    if (!ambientWindow) {
                        alertify.error("Popup blocked! Please allow popups for this site.");
                        return;
                    }

                    // Listen for events from Ambient
                    function receiveAmbientMessage(event) {
                        // Security: verify origin
                        if (event.origin !== "https://ambitious-flower-01bc6170f.7.azurestaticapps.net") {
                            return;
                        }

                        console.log("Ambient Event:", event);

                        if (!event.data || !event.data.type) {
                            return;
                        }

                        // NOTE READY - Fetch and display
                        if (event.data.type === "ambient:noteReady") {
                            var sessionId = event.data.sessionId;
                            var noteId = event.data.noteId;

                            console.log("✅ Note Ready!");
                            console.log("SessionId:", sessionId);
                            console.log("NoteId:", noteId);

                            alertify.success("Ambient note ready! Fetching...");

                            // Fetch the note
                            fetchAmbientNote(sessionId, sessionToken);

                            window.removeEventListener("message", receiveAmbientMessage);
                        }

                        // WINDOW CLOSED
                        if (event.data.type === "ambient:closed") {
                            console.log("Ambient popup closed");
                            window.removeEventListener("message", receiveAmbientMessage);
                        }
                    }

                    window.addEventListener("message", receiveAmbientMessage);

                }, function (err) {
                    console.log(err);
                    alertify.error("Unable to start voice chart");
                });

            // Helper: Fetch note from Ambient API
            function fetchAmbientNote(sessionId, token) {
                var apiUrl = "https://app-ehnote-ai-api.azurewebsites.net";
                var noteUrl = apiUrl + "/api/sessions/" + sessionId + "/structured-notes/latest";

                $http({
                    method: 'GET',
                    url: noteUrl,
                    headers: {
                        'Authorization': 'Bearer ' + token
                    }
                }).then(function (response) {
                    console.log("✅ Ambient Note Received:", response.data);

                    var noteData = response.data.note;

                    // Display the note in console for now
                    console.log("Chief Complaint:", noteData.chiefComplaint);
                    console.log("Visual Acuity OD:", noteData.examFindings?.visualAcuity?.distance?.od);
                    console.log("IOP OD:", noteData.examFindings?.iop?.od);
                    console.log("Diagnoses:", noteData.diagnoses);

                    alertify.success("✅ Note fetched! Check console for data.");

                    // TODO PHASE 2: Import into EHNOTE UI
                    // importNoteIntoChart(noteData);

                }).catch(function (error) {
                    console.error("❌ Failed to fetch note:", error);
                    alertify.error("Failed to retrieve Ambient note");
                });
            }
        };


