        $scope.hasNineGazeData = function (eye) {

            if (!eye) return false;

            var positions = [
                "UpLeft", "Up", "UpRight",
                "Left", "Primary", "Right",
                "DownLeft", "Down", "DownRight"
            ];

            for (var i = 0; i < positions.length; i++) {

                var pos = eye[positions[i]];

                if (!pos) continue;

                if ((pos.H && (pos.H.Amount || pos.H.Direction)) ||
                    (pos.V && (pos.V.Amount || pos.V.Direction))) {
                    return true;
                }
            }

            return false;
        };

        $scope.showHeadPosture = function (details) {
            if (!details || !details.length) return false;

            return details.some(function (inv) {
                return inv.InvestigationId === 698 &&
                    (
                        inv.HeadTiltValue ||
                        inv.FaceTurnValue ||
                        inv.ChinPositionValue ||

                        inv.HeadTiltAngle ||
                        inv.HeadTiltPrism ||
                        inv.HeadTiltDeviationId > 0 ||
                        inv.HeadTiltDeviationName ||

                        inv.FaceTurnAngle ||
                        inv.FaceTurnPrismValue ||
                        inv.FaceTurnDeviationId > 0 ||
                        inv.FaceTurnDeviationName ||

                        inv.ChinPositionAngle ||
                        inv.ChinPositionPrismValue ||
                        inv.ChinPositionDeviationId > 0 ||
                        inv.ChinPositionDeviationName 
                    );
            });
        };

        $scope.IsContactLensDataAvailable = function () {
            if (!$scope.cacheStorageItem.ContactLensDetails ||
                $scope.cacheStorageItem.ContactLensDetails.length === 0) {
                return false;
            }

            return $scope.cacheStorageItem.ContactLensDetails.some(function (contactLens) {
                return contactLens.DeleteInd !== 'Y' &&
                    contactLens.InvestigationDetails &&
                    contactLens.InvestigationDetails.some(function (detail) {
                        return detail.DeleteInd !== 'Y';
                    });
            });
        };

